// プレゼン教科書 Week 27〜33
window.PRESENT=(window.PRESENT||[]).concat([
 {week:27, level:"A2", length:"2分", title:"会社・事業紹介の型",
  skill:"経歴（過去形）→ 今の仕事（現在形）→ これから、の順で、取引先に2分の会社・事業紹介ができるようになる。",
  lesson:[
   "取引先への会社・事業紹介は、「だれか → どんな道を通ってきたか → 今なにをしているか → 相手と何ができるか」の順で話すと伝わります。今週の文法、過去形と -ने से पहले（〜する前に）・-ने के बाद（〜した後で）は、この「道のり」を話すための道具です。",
   "経歴は年の順に並べます。2018 में（2018年に）、उसके बाद（その後）、तब से（それ以来）をつなぎにすると、聞き手は時間の流れを追いやすくなります。「生まれた・なった」は自動詞なので ने はつかず、「開いた・作った」は他動詞なので मैंने を使います。",
   "経歴を話したら、必ず現在形にもどります。「8年前から院を経営しています」は आठ साल से … चला रहा हूँ。過去の話で終わらず、「今、何をしている人か」をはっきり言うと、取引先は次の話をしやすくなります。",
   "事業がいくつもあるときは、最初に「3種類の仕事をしています」と数を言ってから、पहला・दूसरा・तीसरा で1つずつ話しましょう。最後は相手への感謝と「一緒に働けたらうれしいです」で終えると、ヒンディー語らしい温かい締めになります。"
  ],
  structure:[
   {hi:"अभिवादन",rom:"abhivādan",ja:"あいさつと感謝"},
   {hi:"परिचय",rom:"parichay",ja:"名前と出身"},
   {hi:"मेरा सफ़र",rom:"merā safar",ja:"経歴（-ने से पहले・के बाद）"},
   {hi:"आज का काम",rom:"āj kā kām",ja:"今の仕事（3つ）"},
   {hi:"समापन",rom:"samāpan",ja:"大切にしていること・締め"}
  ],
  phrases:[
   {hi:"आज मैं अपना छोटा-सा परिचय देना चाहता हूँ।",rom:"āj maiṁ apnā chhoṭā-sā parichay denā chāhtā hūṁ.",ja:"今日は簡単に自己紹介をさせてください。",note:"決まり文句として覚える。चाहता हूँ＝〜したいです。"},
   {hi:"मैं योकोहामा में पैदा हुआ।",rom:"maiṁ Yokohāmā meṁ paidā huā.",ja:"横浜で生まれました。",note:"「生まれる」は自動詞なので मैंने にしない。"},
   {hi:"क्लिनिक खोलने से पहले मैं एथलेटिक ट्रेनर था।",rom:"klinik kholne se pahle maiṁ ethleṭik ṭrenar thā.",ja:"院を開く前は、アスレティックトレーナーでした。",note:"-ना を -ने にして से पहले。順番は日本語と同じ。"},
   {hi:"मैंने अक्टूबर 2018 में ओज़ू में क्लिनिक खोला।",rom:"maiṁne akṭūbar 2018 meṁ Ozū meṁ klinik kholā.",ja:"2018年10月に大洲で院を開きました。",note:"年や月には में。क्लिनिक は男性名詞なので खोला。"},
   {hi:"मैं आठ साल से यह क्लिनिक चला रहा हूँ।",rom:"maiṁ āṭh sāl se yah klinik chalā rahā hūṁ.",ja:"8年前からこの院を経営しています。",note:"今も続いていることは「数＋साल से」＋進行形。"},
   {hi:"क्लिनिक खोलने के बाद मैंने एक बुकिंग सिस्टम बनाया।",rom:"klinik kholne ke bād maiṁne ek buking sisṭam banāyā.",ja:"院を開いた後、予約のシステムを作りました。",note:"-ने के बाद＝〜した後で。経歴の2つ目の山場に使う。"},
   {hi:"तब से हमारे पार्टनर क्लिनिक भी यह सिस्टम इस्तेमाल करते हैं।",rom:"tab se hamāre pārṭnar klinik bhī yah sisṭam istemāl karte haiṁ.",ja:"それ以来、提携院もこのシステムを使っています。",note:"तब से＝それ以来。過去から今へ話を橋わたしする。"},
   {hi:"आज मैं तीन तरह का काम करता हूँ।",rom:"āj maiṁ tīn tarah kā kām kartā hūṁ.",ja:"今は3種類の仕事をしています。",note:"先に数を言うと、聞き手は地図を持って聞ける。"},
   {hi:"मैं परिवार की दुकान में इंटरनेशनल काम देखता हूँ।",rom:"maiṁ parivār kī dukān meṁ inṭarneshanal kām dekhtā hūṁ.",ja:"家族の店で海外の仕事を担当しています。",note:"देखना は仕事では「担当する」。"},
   {hi:"आपके साथ काम करके मुझे बहुत ख़ुशी होगी।",rom:"āpke sāth kām karke mujhe bahut khushī hogī.",ja:"ご一緒にお仕事ができたら、とてもうれしいです。",note:"締めの決まり文句として覚える。-कर＋未来形。"}
  ],
  model:{title:"取引先の新しい担当者への会社・事業紹介", time:"2分", note:"年・人数・事業は本人の事実です。区切りごとに少し間をとって話しましょう。", lines:[
   {hi:"नमस्कार! आपके समय के लिए बहुत धन्यवाद।",rom:"namaskār! āpke samay ke lie bahut dhanyavād.",ja:"こんにちは。お時間をいただき、ありがとうございます。"},
   {hi:"मेरा नाम आकिहिरो इवाता है। आज मैं अपना छोटा-सा परिचय देना चाहता हूँ।",rom:"merā nām Ākihiro Ivātā hai. āj maiṁ apnā chhoṭā-sā parichay denā chāhtā hūṁ.",ja:"岩田章弘と申します。今日は簡単に自己紹介をさせてください。"},
   {hi:"मैं योकोहामा में पैदा हुआ। योकोहामा टोक्यो के पास एक बड़ा शहर है।",rom:"maiṁ Yokohāmā meṁ paidā huā. Yokohāmā Ṭokyo ke pās ek baṛā shahar hai.",ja:"横浜で生まれました。横浜は東京の近くの大きな町です。"},
   {hi:"क्लिनिक खोलने से पहले मैं एथलेटिक ट्रेनर था।",rom:"klinik kholne se pahle maiṁ ethleṭik ṭrenar thā.",ja:"院を開く前は、アスレティックトレーナーでした。"},
   {hi:"मैंने हाई स्कूल, यूनिवर्सिटी, कंपनी और प्रोफ़ेशनल स्पोर्ट्स टीमों के साथ काम किया।",rom:"maiṁne hāī skūl, yūnivarsiṭī, kampanī aur profeshanal sporṭs ṭīmoṁ ke sāth kām kiyā.",ja:"高校、大学、実業団、プロのスポーツチームと一緒に仕事をしました。"},
   {hi:"उसके बाद मैंने अक्टूबर 2018 में ओज़ू, एहिमे में अपना क्लिनिक खोला।",rom:"uske bād maiṁne akṭūbar 2018 meṁ Ozū, Ehime meṁ apnā klinik kholā.",ja:"その後、2018年10月に愛媛県の大洲で自分の院を開きました。"},
   {hi:"मैं आठ साल से यह क्लिनिक चला रहा हूँ। हमारी टीम में चार स्टाफ़ हैं।",rom:"maiṁ āṭh sāl se yah klinik chalā rahā hūṁ. hamārī ṭīm meṁ chār sṭāf haiṁ.",ja:"8年前からこの院を経営しています。チームにはスタッフが4名います。"},
   {hi:"क्लिनिक में मैं हर दिन तीन नंबर देखता हूँ: बिक्री, मरीज़ों की संख्या और दोबारा आने की दर।",rom:"klinik meṁ maiṁ har din tīn nambar dekhtā hūṁ: bikrī, marīzoṁ kī sankhyā aur dobārā āne kī dar.",ja:"院では毎日3つの数字を見ています。売上、来院数、そして再来院率です。"},
   {hi:"इसके लिए मैंने अपना बुकिंग और कस्टमर सिस्टम बनाया।",rom:"iske lie maiṁne apnā buking aur kasṭamar sisṭam banāyā.",ja:"そのために、自分で予約・顧客管理のシステムを作りました。"},
   {hi:"तब से हमारे पार्टनर क्लिनिक भी यह सिस्टम इस्तेमाल करते हैं। मैं उनके मैनेजमेंट में भी मदद करता हूँ।",rom:"tab se hamāre pārṭnar klinik bhī yah sisṭam istemāl karte haiṁ. maiṁ unke mainejmenṭ meṁ bhī madad kartā hūṁ.",ja:"それ以来、提携院もこのシステムを使っています。提携院の経営のお手伝いもしています。"},
   {hi:"आज मैं तीन तरह का काम करता हूँ।",rom:"āj maiṁ tīn tarah kā kām kartā hūṁ.",ja:"今は3種類の仕事をしています。"},
   {hi:"पहला, क्लिनिक और पार्टनर क्लिनिक का काम।",rom:"pahlā, klinik aur pārṭnar klinik kā kām.",ja:"1つ目は、院と提携院の仕事です。"},
   {hi:"दूसरा, भारत के होटल, रेस्टोरेंट और क्लिनिक के लिए ओमोतेनाशी कंसल्टिंग।",rom:"dūsrā, Bhārat ke hoṭal, resṭoranṭ aur klinik ke lie omotenāshī kansalṭing.",ja:"2つ目は、インドのホテル・レストラン・クリニック向けの「おもてなし」コンサルティングです。"},
   {hi:"ओमोतेनाशी का मतलब है, दिल से मेहमान का स्वागत।",rom:"omotenāshī kā matlab hai, dil se mehmān kā svāgat.",ja:"おもてなしとは、心からお客様をお迎えすることです。"},
   {hi:"तीसरा, मैं परिवार की दुकान में इंटरनेशनल काम देखता हूँ। यह साके की दुकान 1957 में शुरू हुई।",rom:"tīsrā, maiṁ parivār kī dukān meṁ inṭarneshanal kām dekhtā hūṁ. yah sāke kī dukān 1957 meṁ shurū huī.",ja:"3つ目は、家族の店で海外の仕事を担当しています。この酒店は1957年に始まりました。"},
   {hi:"मेरे लिए सबसे ज़रूरी बात है: सामने वाले इंसान के लिए पूरी कोशिश करना।",rom:"mere lie sabse zarūrī bāt hai: sāmne vāle insān ke lie pūrī koshish karnā.",ja:"私がいちばん大切にしているのは、目の前の人に全力を尽くすことです。"},
   {hi:"आपके साथ काम करके मुझे बहुत ख़ुशी होगी। बहुत-बहुत धन्यवाद।",rom:"āpke sāth kām karke mujhe bahut khushī hogī. bahut-bahut dhanyavād.",ja:"ご一緒にお仕事ができたら、とてもうれしいです。ありがとうございました。"}
  ]},
  task:"インドの取引先の新しい担当者に、2分で会社・事業紹介をする。生まれ・院を開く前・開いた後（-ने से पहले／के बाद）・今の3つの仕事・大切にしていることを、年の順に入れる。",
  taskEn:"Give a two-minute company and business introduction to a new contact at an Indian partner company. In time order, cover where you were born, what you did before and after opening your clinic, your three current lines of work, and what you value most.",
  qa:[
   {q:"आप कब से क्लिनिक चला रहे हैं?",qRom:"āp kab se klinik chalā rahe haiṁ?",a:"मैं 2018 से क्लिनिक चला रहा हूँ। लगभग आठ साल हो गए।",aRom:"maiṁ 2018 se klinik chalā rahā hūṁ. lagbhag āṭh sāl ho gae.",ja:"質問：いつから院を経営していますか。／答え：2018年から経営しています。もうすぐ8年になります。"},
   {q:"क्लिनिक खोलने से पहले आपका काम क्या था?",qRom:"klinik kholne se pahle āpkā kām kyā thā?",a:"मैं एथलेटिक ट्रेनर था। मैंने कई स्पोर्ट्स टीमों के साथ काम किया।",aRom:"maiṁ ethleṭik ṭrenar thā. maiṁne kaī sporṭs ṭīmoṁ ke sāth kām kiyā.",ja:"質問：院を開く前は、どんなお仕事でしたか。／答え：アスレティックトレーナーでした。いくつものスポーツチームと仕事をしました。"},
   {q:"ओमोतेनाशी कंसल्टिंग में आप क्या करते हैं?",qRom:"omotenāshī kansalṭing meṁ āp kyā karte haiṁ?",a:"होटल, रेस्टोरेंट और क्लिनिक जापानी मेहमानों का स्वागत करते हैं। मैं उसमें उनकी मदद करता हूँ।",aRom:"hoṭal, resṭoranṭ aur klinik jāpānī mehmānoṁ kā svāgat karte haiṁ. maiṁ usmeṁ unkī madad kartā hūṁ.",ja:"質問：おもてなしコンサルティングでは何をしていますか。／答え：ホテルやレストラン、クリニックが日本人のお客様をお迎えします。そのお手伝いをしています。"}
  ],
  check:[
   "経歴を年の順に話せたか（横浜 → トレーナー → 2018年 → 今）",
   "-ने से पहले と -ने के बाद を1回ずつ使えたか",
   "「生まれた」に ने をつけず、「開いた・作った」に मैंने を使えたか",
   "経歴のあと、現在形（चला रहा हूँ・देखता हूँ）にもどれたか",
   "3つの仕事を पहला・दूसरा・तीसरा で区切れたか"
  ],
  slide:"左から右へ矢印の「年表」を1枚。横浜 → トレーナー → 2018 大洲 → 今の3つの仕事、と4つの点だけを大きく書きます。"},

 {week:28, level:"A2", length:"2分30秒", title:"聞き手に合わせて話す",
  skill:"最初に聞き手の出身や関心をたずね、その答えに合わせて話の順番を変えられるようになる。",
  lesson:[
   "同じ内容でも、聞き手によって「入り口」を変えると、話はずっと届きやすくなります。インドは州ごとに言葉も食べ物も違うので、最初に出身を聞くのはとても自然で、相手も喜んで答えてくれます。",
   "出身は रहने वाला で聞きます。聞き手全体には आप में से कौन-कौन … के रहने वाले हैं?（皆さんの中で、どなたが〜のご出身ですか）。手を挙げてもらうときは हाथ उठाइए と言います。答えてくれた人には、名前に जी をつけて呼びかけましょう。",
   "次に関心を聞きます。किसको … पसंद है?（どなたが〜がお好きですか）。答えを見て「では、今日は〜から話します」と順番を変えます。तो आज मैं पहले … की बात करूँगा। の1文があれば、準備した話を入れかえるだけで聞き手に合わせられます。",
   "自分の出身も -वाला で言えます：मैं योकोहामा का रहने वाला हूँ। दिल्ली वाले（デリーの人たち）のように、-वाला は「〜の人」にもなります。相手の町の話題を1つ用意しておくと、聞き手との距離が一気に縮まります。"
  ],
  structure:[
   {hi:"अभिवादन",rom:"abhivādan",ja:"あいさつと自己紹介"},
   {hi:"पहला सवाल",rom:"pahlā savāl",ja:"出身を聞く（रहने वाले）"},
   {hi:"दूसरा सवाल",rom:"dūsrā savāl",ja:"関心を聞く（किसको … पसंद है）"},
   {hi:"आज का क्रम",rom:"āj kā kram",ja:"答えに合わせて話の順番を決める"},
   {hi:"समापन",rom:"samāpan",ja:"聞き手の話も聞きたい、で締める"}
  ],
  phrases:[
   {hi:"आप में से कौन-कौन दिल्ली के रहने वाले हैं?",rom:"āp meṁ se kaun-kaun Dillī ke rahne vāle haiṁ?",ja:"皆さんの中で、デリーご出身の方はどなたですか。",note:"कौन-कौन で「どなたとどなた」と全員に聞く。"},
   {hi:"कृपया हाथ उठाइए।",rom:"kripayā hāth uṭhāie.",ja:"手を挙げてください。",note:"自分も手を挙げて見せると伝わりやすい。"},
   {hi:"राज जी, आप कहाँ के रहने वाले हैं?",rom:"Rāj jī, āp kahāṁ ke rahne vāle haiṁ?",ja:"ラジさん、ご出身はどちらですか。",note:"女性には कहाँ की रहने वाली हैं?"},
   {hi:"मैं योकोहामा का रहने वाला हूँ, लेकिन अब एहिमे में रहता हूँ।",rom:"maiṁ Yokohāmā kā rahne vālā hūṁ, lekin ab Ehime meṁ rahtā hūṁ.",ja:"私は横浜の出身ですが、今は愛媛に住んでいます。",note:"出身と今の住まいを1文で。"},
   {hi:"अच्छा, बहुत लोग मुंबई के हैं!",rom:"achchhā, bahut log Mumbaī ke haiṁ!",ja:"なるほど、ムンバイの方が多いですね！",note:"答えをくり返すと、聞いていることが伝わる。"},
   {hi:"आप में से किसको जापानी खाना पसंद है?",rom:"āp meṁ se kisko jāpānī khānā pasand hai?",ja:"皆さんの中で、日本の食べ物が好きな方は？",note:"पसंद は को の形で。कौन ではなく किसको。"},
   {hi:"तो आज मैं पहले खाने की बात करूँगा।",rom:"to āj maiṁ pahle khāne kī bāt karūṁgā.",ja:"では今日は、まず食べ物の話をします。",note:"答えに合わせて順番を変える合図の1文。"},
   {hi:"दिल्ली वालों को खाना बहुत पसंद है, है ना?",rom:"Dillī vāloṁ ko khānā bahut pasand hai, hai nā?",ja:"デリーの方は食べることが大好きですよね？",note:"है ना? で同意を求めると場がなごむ。"},
   {hi:"बाद में आपके शहर के बारे में मुझे ज़रूर बताइए।",rom:"bād meṁ āpke shahar ke bāre meṁ mujhe zarūr batāie.",ja:"あとで、ぜひ皆さんの町のことを教えてください。",note:"話す人から聞く人へ、立場を入れかえる締め。"},
   {hi:"मैं आपकी राय भी सुनना चाहता हूँ।",rom:"maiṁ āpkī rāy bhī sunnā chāhtā hūṁ.",ja:"皆さんのご意見もお聞きしたいです。",note:"決まり文句として覚える。राय＝意見（女）。"}
  ],
  model:{title:"出身と関心を聞いてから始める事業紹介", time:"2分30秒", note:"手の数や答えは練習用の例です。その場の答えに合わせて言いかえましょう。", lines:[
   {hi:"नमस्ते, आप सब को! प्रिया जी, मुझे यहाँ बुलाने के लिए धन्यवाद।",rom:"namaste, āp sab ko! Priyā jī, mujhe yahāṁ bulāne ke lie dhanyavād.",ja:"皆さん、こんにちは。プリヤさん、お招きいただきありがとうございます。"},
   {hi:"मेरा नाम आकिहिरो इवाता है। मैं योकोहामा का रहने वाला हूँ, लेकिन अब एहिमे में रहता हूँ।",rom:"merā nām Ākihiro Ivātā hai. maiṁ Yokohāmā kā rahne vālā hūṁ, lekin ab Ehime meṁ rahtā hūṁ.",ja:"岩田章弘と申します。横浜の出身ですが、今は愛媛に住んでいます。"},
   {hi:"शुरू करने से पहले मैं आपसे दो सवाल पूछना चाहता हूँ।",rom:"shurū karne se pahle maiṁ āpse do savāl pūchhnā chāhtā hūṁ.",ja:"始める前に、皆さんに2つ質問をさせてください。"},
   {hi:"पहला सवाल: आप में से कौन-कौन दिल्ली के रहने वाले हैं? कृपया हाथ उठाइए।",rom:"pahlā savāl: āp meṁ se kaun-kaun Dillī ke rahne vāle haiṁ? kripayā hāth uṭhāie.",ja:"1つ目の質問です。皆さんの中で、デリーご出身の方は？手を挙げてください。"},
   {hi:"अच्छा, आधे लोग दिल्ली के हैं। और बाक़ी लोग?",rom:"achchhā, ādhe log Dillī ke haiṁ. aur bāqī log?",ja:"なるほど、半分の方がデリーですね。ほかの方は？"},
   {hi:"राज जी, आप कहाँ के रहने वाले हैं? अच्छा, बेंगलुरु के! बढ़िया।",rom:"Rāj jī, āp kahāṁ ke rahne vāle haiṁ? achchhā, Bengaluru ke! baṛhiyā.",ja:"ラジさん、ご出身はどちらですか。（答えを聞いて）ああ、ベンガルールですね！いいですね。"},
   {hi:"भारत में हर राज्य का खाना और भाषा अलग है। यह मुझे बहुत अच्छा लगता है।",rom:"Bhārat meṁ har rājya kā khānā aur bhāshā alag hai. yah mujhe bahut achchhā lagtā hai.",ja:"インドでは州ごとに食べ物も言葉も違います。それがとてもすてきだと思います。"},
   {hi:"दूसरा सवाल: आप में से किसको जापानी खाना पसंद है?",rom:"dūsrā savāl: āp meṁ se kisko jāpānī khānā pasand hai?",ja:"2つ目の質問です。皆さんの中で、日本の食べ物が好きな方は？"},
   {hi:"वाह, बहुत हाथ हैं! और किसको साके के बारे में मालूम है?",rom:"vāh, bahut hāth haiṁ! aur kisko sāke ke bāre meṁ mālūm hai?",ja:"わあ、たくさん手が挙がりましたね！では、日本酒のことを知っている方は？"},
   {hi:"अच्छा, कुछ लोगों को मालूम है। तो आज मैं पहले खाने और साके की बात करूँगा।",rom:"achchhā, kuchh logoṁ ko mālūm hai. to āj maiṁ pahle khāne aur sāke kī bāt karūṁgā.",ja:"なるほど、何人かはご存じですね。では今日は、まず食べ物と日本酒の話をします。"},
   {hi:"दिल्ली वालों को खाना बहुत पसंद है, है ना?",rom:"Dillī vāloṁ ko khānā bahut pasand hai, hai nā?",ja:"デリーの方は食べることが大好きですよね？"},
   {hi:"मेरे परिवार की एक साके की दुकान है। यह दुकान 1957 में शुरू हुई।",rom:"mere parivār kī ek sāke kī dukān hai. yah dukān 1957 meṁ shurū huī.",ja:"私の家族は酒店をしています。この店は1957年に始まりました。"},
   {hi:"मैं उस दुकान में इंटरनेशनल काम देखता हूँ।",rom:"maiṁ us dukān meṁ inṭarneshanal kām dekhtā hūṁ.",ja:"私はその店で海外の仕事を担当しています。"},
   {hi:"साके जापान की चावल की शराब है। जापान में लोग खाने के साथ साके पीते हैं।",rom:"sāke Jāpān kī chāval kī sharāb hai. Jāpān meṁ log khāne ke sāth sāke pīte haiṁ.",ja:"日本酒は日本のお米のお酒です。日本では、食事と一緒に日本酒を飲みます。"},
   {hi:"उसके बाद मैं अपने क्लिनिक और ओमोतेनाशी के काम की बात करूँगा।",rom:"uske bād maiṁ apne klinik aur omotenāshī ke kām kī bāt karūṁgā.",ja:"そのあとで、私の院とおもてなしの仕事の話をします。"},
   {hi:"ओमोतेनाशी में भी सबसे पहले हम मेहमान से पूछते हैं: आप कहाँ से हैं, आपको क्या पसंद है?",rom:"omotenāshī meṁ bhī sabse pahle ham mehmān se pūchhte haiṁ: āp kahāṁ se haiṁ, āpko kyā pasand hai?",ja:"おもてなしでも、まず最初にお客様に聞きます。どちらからいらしたか、何がお好きか。"},
   {hi:"आज मैंने भी आपसे यही पूछा।",rom:"āj maiṁne bhī āpse yahī pūchhā.",ja:"今日、私も皆さんに同じことをお聞きしました。"},
   {hi:"बाद में आपके शहर के बारे में मुझे ज़रूर बताइए। मैं आपकी राय भी सुनना चाहता हूँ।",rom:"bād meṁ āpke shahar ke bāre meṁ mujhe zarūr batāie. maiṁ āpkī rāy bhī sunnā chāhtā hūṁ.",ja:"あとで、ぜひ皆さんの町のことを教えてください。ご意見もお聞きしたいです。"},
   {hi:"चलिए, शुरू करते हैं। धन्यवाद!",rom:"chalie, shurū karte haiṁ. dhanyavād!",ja:"では、始めましょう。ありがとうございます！"}
  ]},
  task:"インドの取引先のチームの前で、2分30秒の事業紹介をする。最初に出身と関心を2つ質問し、答えに合わせて「食べ物と日本酒」か「院とおもてなし」のどちらから話すかを決める。",
  taskEn:"Give a two-and-a-half-minute business introduction to a partner company's team in India. Start by asking two questions about where they are from and what they are interested in, and then choose whether to begin with Japanese food and sake or with your clinic and hospitality work.",
  qa:[
   {q:"आप कहाँ के रहने वाले हैं?",qRom:"āp kahāṁ ke rahne vāle haiṁ?",a:"मैं योकोहामा का रहने वाला हूँ। अब मैं एहिमे के ओज़ू शहर में रहता हूँ।",aRom:"maiṁ Yokohāmā kā rahne vālā hūṁ. ab maiṁ Ehime ke Ozū shahar meṁ rahtā hūṁ.",ja:"質問：ご出身はどちらですか。／答え：横浜の出身です。今は愛媛の大洲という町に住んでいます。"},
   {q:"आप भारत कितनी बार आते हैं?",qRom:"āp Bhārat kitnī bār āte haiṁ?",a:"मैं अक्सर भारत आता हूँ। यहाँ मेरे पार्टनर और दोस्त हैं।",aRom:"maiṁ aksar Bhārat ātā hūṁ. yahāṁ mere pārṭnar aur dost haiṁ.",ja:"質問：インドにはどれくらい来ていますか。／答え：よく来ています。ここに取引先と仲間がいるんです。"},
   {q:"आप पहले खाने की बात क्यों कर रहे हैं?",qRom:"āp pahle khāne kī bāt kyoṁ kar rahe haiṁ?",a:"क्योंकि यहाँ बहुत लोगों को जापानी खाना पसंद है। मैं आपकी पसंद से शुरू करना चाहता हूँ।",aRom:"kyonki yahāṁ bahut logoṁ ko jāpānī khānā pasand hai. maiṁ āpkī pasand se shurū karnā chāhtā hūṁ.",ja:"質問：なぜ食べ物の話から始めるのですか。／答え：ここには日本の食べ物が好きな方が多いからです。皆さんの好きなことから始めたいんです。"}
  ],
  check:[
   "質問を2つ（出身・関心）してから本題に入れたか",
   "रहने वाले／रहने वाली を相手の男女に合わせられたか",
   "答えてくれた人を「名前＋जी」で呼べたか",
   "答えをくり返し（अच्छा, …!）、聞いていることを示せたか",
   "तो आज मैं पहले … の1文で、話の順番を決められたか"
  ],
  slide:"1枚目はインドの地図と日本の地図を並べ、「आप कहाँ के रहने वाले हैं?」と1行だけ大きく。聞き手が答えやすい入り口にします。"},

 {week:29, level:"A2", length:"2分30秒", title:"おもてなしの提案（ホテル・レストラン向け）",
  skill:"ホテルやレストランの方に、日本人のお客様の気持ちと、おもてなしでできることを短く提案し、ていねいに次の話へつなげられるようになる。",
  lesson:[
   "商談の冒頭では、いきなりサービスの中身を話すより、まず相手のお客様の話から始めます。「日本からのお客様は、こんなとき、こう感じます」と具体的な場面を1つ見せると、ホテルやレストランの方は自分のこととして聞いてくれます。",
   "今週の文法の「勧める・断る」は、そのまま提案の材料になります。日本人は遠慮（संकोच）して、本当はほしくても बस（もう十分です）と言いがちです。この日本人らしさをインドの方に説明すると、おもてなしの意味がよく伝わります。",
   "提案は「小さく・具体的に」。名前を覚えて呼ぶ、料理の辛さを先に聞く、部屋にスリッパを置く、など、明日からできることを3つほど示しましょう。実績の数字は言わず、場面で語ります。数字がなくても、場面がはっきりしていれば相手の心に残ります。",
   "締めには、ていねいな -इएगा を使います。ज़रूर सोचिएगा（ぜひご検討ください）、बताइएगा（お知らせくださいね）。命令形の -इए よりやわらかく、「あとで、ゆっくりで結構です」という気持ちが伝わります。細かい条件の話は英語に切り替えてかまいません。"
  ],
  structure:[
   {hi:"अभिवादन और धन्यवाद",rom:"abhivādan aur dhanyavād",ja:"あいさつと感謝"},
   {hi:"मेहमान की कहानी",rom:"mehmān kī kahānī",ja:"日本人のお客様の場面"},
   {hi:"ओमोतेनाशी क्या है",rom:"omotenāshī kyā hai",ja:"おもてなしとは"},
   {hi:"तीन छोटे क़दम",rom:"tīn chhoṭe qadam",ja:"明日からできる3つの提案"},
   {hi:"अगला क़दम",rom:"aglā qadam",ja:"ご検討のお願い（-इएगा）"}
  ],
  phrases:[
   {hi:"आज मुझे समय देने के लिए आपका बहुत धन्यवाद।",rom:"āj mujhe samay dene ke lie āpkā bahut dhanyavād.",ja:"今日はお時間をいただき、ありがとうございます。",note:"商談の最初の1文。決まり文句として覚える。"},
   {hi:"जापानी मेहमान अक्सर संकोच करते हैं।",rom:"jāpānī mehmān aksar sankoch karte haiṁ.",ja:"日本人のお客様は、よく遠慮します。",note:"संकोच＝遠慮。日本人らしさを説明するキーワード。"},
   {hi:"कई बार वे ‘बस’ कहते हैं, लेकिन असल में और चाहते हैं।",rom:"kaī bār ve ‘bas’ kahte haiṁ, lekin asal meṁ aur chāhte haiṁ.",ja:"「もう十分です」と言っても、本当はもっとほしいことがよくあります。",note:"今週の बस（もう十分）をそのまま使う。"},
   {hi:"ओमोतेनाशी का मतलब है, मेहमान के कहने से पहले उनकी ज़रूरत समझना।",rom:"omotenāshī kā matlab hai, mehmān ke kahne se pahle unkī zarūrat samajhnā.",ja:"おもてなしとは、お客様が言う前に、必要なことを察することです。",note:"先週の -ने से पहले の復習。この1文が提案の芯。"},
   {hi:"मेहमान का नाम याद रखिए और नाम से बुलाइए।",rom:"mehmān kā nām yād rakhie aur nām se bulāie.",ja:"お客様の名前を覚えて、名前でお呼びください。",note:"提案は -इए の形で短く。"},
   {hi:"खाने से पहले पूछिए: आपको कितना तीखा पसंद है?",rom:"khāne se pahle pūchhie: āpko kitnā tīkhā pasand hai?",ja:"食事の前に「辛さはどれくらいがお好きですか」と聞いてください。",note:"तीखा＝辛い。具体的なせりふまで見せる。"},
   {hi:"ये छोटी बातें हैं, लेकिन मेहमान इन्हें हमेशा याद रखते हैं।",rom:"ye chhoṭī bāteṁ haiṁ, lekin mehmān inheṁ hameshā yād rakhte haiṁ.",ja:"小さなことですが、お客様はずっと覚えています。",note:"数字の代わりに、気持ちで理由を言う。"},
   {hi:"मैं आपकी टीम के साथ मिलकर यह तैयारी कर सकता हूँ।",rom:"maiṁ āpkī ṭīm ke sāth milkar yah taiyārī kar saktā hūṁ.",ja:"皆さんのチームと一緒に、この準備ができます。",note:"सकना で「できる手伝い」を言う。"},
   {hi:"कृपया इस बारे में ज़रूर सोचिएगा।",rom:"kripayā is bāre meṁ zarūr sochiegā.",ja:"ぜひご検討ください。",note:"-इएगा は -इए よりやわらかい「どうぞ〜してくださいね」。"},
   {hi:"कोई सवाल हो तो बताइएगा।",rom:"koī savāl ho to batāiegā.",ja:"ご質問があれば、お知らせくださいね。",note:"決まり文句として覚える。"}
  ],
  model:{title:"ホテル・レストランへのおもてなしの提案（冒頭）", time:"2分30秒", note:"場面は練習用の例です。実績の数字は入れず、場面で伝えましょう。", lines:[
   {hi:"नमस्ते, आप सब को। आज मुझे समय देने के लिए आपका बहुत धन्यवाद।",rom:"namaste, āp sab ko. āj mujhe samay dene ke lie āpkā bahut dhanyavād.",ja:"皆さん、こんにちは。今日はお時間をいただき、ありがとうございます。"},
   {hi:"मेरा नाम आकिहिरो इवाता है। मैं जापान में एक क्लिनिक चलाता हूँ।",rom:"merā nām Ākihiro Ivātā hai. maiṁ Jāpān meṁ ek klinik chalātā hūṁ.",ja:"岩田章弘と申します。日本で院を経営しています。"},
   {hi:"साथ ही मैं भारत की कंपनियों के साथ ओमोतेनाशी का काम करता हूँ।",rom:"sāth hī maiṁ Bhārat kī kampaniyoṁ ke sāth omotenāshī kā kām kartā hūṁ.",ja:"あわせて、インドの企業と「おもてなし」の仕事をしています。"},
   {hi:"आज मैं एक छोटा-सा प्रस्ताव देना चाहता हूँ। पहले एक छोटी-सी कहानी सुनिए।",rom:"āj maiṁ ek chhoṭā-sā prastāv denā chāhtā hūṁ. pahle ek chhoṭī-sī kahānī sunie.",ja:"今日は小さなご提案をしたいと思います。まず、短いお話を聞いてください。"},
   {hi:"एक जापानी मेहमान आपके रेस्टोरेंट में खाना खा रहे हैं।",rom:"ek jāpānī mehmān āpke resṭoranṭ meṁ khānā khā rahe haiṁ.",ja:"日本人のお客様が、こちらのレストランで食事をしています。"},
   {hi:"वेटर पूछता है: थोड़ा और लीजिए? मेहमान मुस्कुराकर कहते हैं: बस, धन्यवाद।",rom:"veṭar pūchhtā hai: thoṛā aur lījie? mehmān muskurākar kahte haiṁ: bas, dhanyavād.",ja:"ウェイターが「もう少しいかがですか」と聞きます。お客様は笑顔で「もう十分です、ありがとう」と言います。"},
   {hi:"लेकिन असल में उन्हें थोड़ा और चाहिए। जापानी लोग अक्सर संकोच करते हैं।",rom:"lekin asal meṁ unheṁ thoṛā aur chāhie. jāpānī log aksar sankoch karte haiṁ.",ja:"でも本当は、もう少しほしいのです。日本人はよく遠慮します。"},
   {hi:"भारत में मेहमान को दो-तीन बार प्यार से कहते हैं। यह बहुत सुंदर रिवाज है।",rom:"Bhārat meṁ mehmān ko do-tīn bār pyār se kahte haiṁ. yah bahut sundar rivāj hai.",ja:"インドでは、お客様に2回3回と心をこめて勧めますね。とてもすてきな習慣です。"},
   {hi:"जापान में तरीक़ा थोड़ा अलग है।",rom:"Jāpān meṁ tarīqā thoṛā alag hai.",ja:"日本では、やり方が少し違います。"},
   {hi:"ओमोतेनाशी का मतलब है, मेहमान के कहने से पहले उनकी ज़रूरत समझना।",rom:"omotenāshī kā matlab hai, mehmān ke kahne se pahle unkī zarūrat samajhnā.",ja:"おもてなしとは、お客様が言う前に、必要なことを察することです。"},
   {hi:"तो मेरा प्रस्ताव है: तीन छोटे क़दम।",rom:"to merā prastāv hai: tīn chhoṭe qadam.",ja:"そこで、ご提案は3つの小さな一歩です。"},
   {hi:"पहला, मेहमान का नाम याद रखिए और नाम से बुलाइए।",rom:"pahlā, mehmān kā nām yād rakhie aur nām se bulāie.",ja:"1つ目、お客様の名前を覚えて、名前でお呼びください。"},
   {hi:"दूसरा, खाने से पहले पूछिए: आपको कितना तीखा पसंद है?",rom:"dūsrā, khāne se pahle pūchhie: āpko kitnā tīkhā pasand hai?",ja:"2つ目、食事の前に「辛さはどれくらいがお好きですか」と聞いてください。"},
   {hi:"तीसरा, कमरे में जूते उतारने की जगह और चप्पल रखिए।",rom:"tīsrā, kamre meṁ jūte utārne kī jagah aur chappal rakhie.",ja:"3つ目、お部屋に靴を脱ぐ場所とスリッパを用意してください。"},
   {hi:"ये छोटी बातें हैं, लेकिन मेहमान इन्हें हमेशा याद रखते हैं।",rom:"ye chhoṭī bāteṁ haiṁ, lekin mehmān inheṁ hameshā yād rakhte haiṁ.",ja:"小さなことですが、お客様はずっと覚えています。"},
   {hi:"ख़ुश मेहमान फिर आते हैं और दोस्तों को भी बताते हैं।",rom:"khush mehmān phir āte haiṁ aur dostoṁ ko bhī batāte haiṁ.",ja:"喜んだお客様は、また来てくださり、友だちにも話してくれます。"},
   {hi:"मैं आपकी टीम के साथ मिलकर यह तैयारी कर सकता हूँ।",rom:"maiṁ āpkī ṭīm ke sāth milkar yah taiyārī kar saktā hūṁ.",ja:"皆さんのチームと一緒に、この準備ができます。"},
   {hi:"आज मैं बस शुरुआत बता रहा हूँ। बाक़ी बातें हम अंग्रेज़ी में आराम से कर सकते हैं।",rom:"āj maiṁ bas shuruāt batā rahā hūṁ. bāqī bāteṁ ham angrezī meṁ ārām se kar sakte haiṁ.",ja:"今日は入り口だけをお話ししています。細かいことは、英語でゆっくりお話しできます。"},
   {hi:"कृपया इस बारे में ज़रूर सोचिएगा। बहुत-बहुत धन्यवाद।",rom:"kripayā is bāre meṁ zarūr sochiegā. bahut-bahut dhanyavād.",ja:"ぜひご検討ください。ありがとうございました。"}
  ]},
  task:"インドのホテルかレストランの方に、2分30秒でおもてなしの提案の冒頭を話す。日本人のお客様の場面を1つ、おもてなしの意味を1文、明日からできる小さな提案を3つ入れ、-इएगा で締める。実績の数字は入れない。",
  taskEn:"Give the two-and-a-half-minute opening of a hospitality proposal to a hotel or restaurant in India. Include one scene with a Japanese guest, one sentence on what omotenashi means, and three small steps they can start tomorrow. End politely, and do not quote any results or numbers.",
  qa:[
   {q:"ओमोतेनाशी और अच्छी सर्विस में क्या फ़र्क़ है?",qRom:"omotenāshī aur achchhī sarvis meṁ kyā farq hai?",a:"अच्छी सर्विस में मेहमान माँगते हैं, फिर हम देते हैं। ओमोतेनाशी में हम उनके माँगने से पहले समझते हैं।",aRom:"achchhī sarvis meṁ mehmān māṁgte haiṁ, phir ham dete haiṁ. omotenāshī meṁ ham unke māṁgne se pahle samajhte haiṁ.",ja:"質問：おもてなしと、よいサービスは何が違うのですか。／答え：よいサービスでは、お客様が頼んでから応えます。おもてなしでは、頼まれる前に察します。"},
   {q:"यह काम कितने समय में होगा?",qRom:"yah kām kitne samay meṁ hogā?",a:"यह आपके होटल के हिसाब से तय होगा। हम अगली मीटिंग में अंग्रेज़ी में इसकी बात करेंगे।",aRom:"yah āpke hoṭal ke hisāb se tay hogā. ham aglī mīṭing meṁ angrezī meṁ iskī bāt kareṁge.",ja:"質問：この仕事はどれくらいの期間がかかりますか。／答え：ホテルに合わせて決めます。次の打ち合わせで、英語でくわしくお話しします。"},
   {q:"क्या आप रेस्टोरेंट के स्टाफ़ से भी मिलेंगे?",qRom:"kyā āp resṭoranṭ ke sṭāf se bhī mileṁge?",a:"जी हाँ, ज़रूर। मैं स्टाफ़ से मिलकर उनकी बात भी सुनना चाहता हूँ।",aRom:"jī hāṁ, zarūr. maiṁ sṭāf se milkar unkī bāt bhī sunnā chāhtā hūṁ.",ja:"質問：レストランのスタッフにも会ってくださいますか。／答え：はい、ぜひ。スタッフの方に会って、お話も聞きたいです。"}
  ],
  check:[
   "サービスの説明より先に、お客様の場面から始められたか",
   "बस と संकोच で、日本人の遠慮をわかりやすく説明できたか",
   "インドの習慣をほめてから、日本のやり方を話せたか",
   "提案を3つ、短い -इए の文で言えたか",
   "実績の数字を作らず、-इएगा でていねいに締められたか"
  ],
  slide:"左に「बस, धन्यवाद」と言うお客様の絵、右に3つの小さな一歩を箇条書きで。数字のグラフは入れません。"},

 {week:30, level:"A2", length:"2分30秒", title:"お祭り・季節のあいさつで始めるスピーチ",
  skill:"お祭りのあいさつで話を始め、インドと日本の行事を比べながら、仲間への感謝と願いにつなげるスピーチができるようになる。",
  lesson:[
   "インドの集まりでは、時期に合ったお祭りのあいさつから始めるだけで、場の空気がぱっと明るくなります。ディワリの時期なら आप सब को दिवाली की शुभकामनाएँ!、ホーリーなら होली मुबारक हो! が最初のひとことです。",
   "次に、お祭りを一般の現在形で説明します。दिवाली पर लोग दीये जलाते हैं（ディワリには人々がランプをともします）。「〜のときに」は पर、「〜の前に」は से पहले です。インドの方にとって当たり前のことを日本人のあなたが言うと、「よく知っているね」と喜ばれます。",
   "そこに日本の行事を並べます。जापान में नए साल पर लोग मंदिर जाते हैं（日本ではお正月に神社やお寺へ行きます）。年末の大掃除や家族で過ごすことなど、似ているところを見つけると、聞き手は日本に親しみを感じ、話が「あなたたちと私」の話になります。",
   "最後は、お祭りの意味（光・新しい始まり・家族）を、仲間への感謝と願いにつなげて締めます。勧誘や宣伝は入れず、「皆さんのおかげで」「これからも一緒に」という気持ちだけを伝えましょう。願いの -ए（लाए）は来週の文法ですが、決まり文句として先に使います。"
  ],
  structure:[
   {hi:"त्योहार की बधाई",rom:"tyohār kī badhāī",ja:"お祭りのあいさつ"},
   {hi:"भारत का त्योहार",rom:"Bhārat kā tyohār",ja:"インドの行事を説明する"},
   {hi:"जापान का त्योहार",rom:"Jāpān kā tyohār",ja:"日本の行事と比べる"},
   {hi:"त्योहार का मतलब",rom:"tyohār kā matlab",ja:"お祭りの意味を仲間につなげる"},
   {hi:"धन्यवाद और शुभकामना",rom:"dhanyavād aur shubhkāmnā",ja:"感謝と願い"}
  ],
  phrases:[
   {hi:"आप सब को दिवाली की हार्दिक शुभकामनाएँ!",rom:"āp sab ko divālī kī hārdik shubhkāmnāeṁ!",ja:"皆さん、心からディワリおめでとうございます！",note:"हार्दिक＝心からの。スピーチの最初に大きな声で。"},
   {hi:"होली मुबारक हो, दोस्तों!",rom:"holī mubārak ho, dostoṁ!",ja:"皆さん、ハッピーホーリー！",note:"ホーリーの時期はこちらで始める。"},
   {hi:"दिवाली पर लोग दीये जलाते हैं और घर सजाते हैं।",rom:"divālī par log dīye jalāte haiṁ aur ghar sajāte haiṁ.",ja:"ディワリには、ランプをともし、家を飾ります。",note:"お祭りの「〜のときに」は पर。一般の現在 -ते हैं。"},
   {hi:"दिवाली से पहले लोग घर की सफ़ाई करते हैं।",rom:"divālī se pahle log ghar kī safāī karte haiṁ.",ja:"ディワリの前には、家の掃除をします。",note:"日本の大掃除と比べる前ふりになる。"},
   {hi:"होली पर लोग एक-दूसरे को रंग लगाते हैं।",rom:"holī par log ek-dūsre ko rang lagāte haiṁ.",ja:"ホーリーには、お互いに色をつけ合います。",note:"एक-दूसरे को＝お互いに。"},
   {hi:"जापान में नए साल पर लोग मंदिर जाते हैं।",rom:"Jāpān meṁ nae sāl par log mandir jāte haiṁ.",ja:"日本では、お正月に神社やお寺に行きます。",note:"नया साल は पर の前で नए साल になる。"},
   {hi:"यह मुझे भारत की दिवाली जैसा लगता है।",rom:"yah mujhe Bhārat kī divālī jaisā lagtā hai.",ja:"これは、インドのディワリに似ていると感じます。",note:"… जैसा लगता है＝〜のように感じる。比べる合図。"},
   {hi:"दिवाली अँधेरे से रोशनी की ओर जाने का त्योहार है।",rom:"divālī aṁdhere se roshnī kī or jāne kā tyohār hai.",ja:"ディワリは、暗やみから光へ向かうお祭りです。",note:"お祭りの意味を1文で言う決まり文句として覚える。"},
   {hi:"मेरे लिए आप सब भी एक दीये की तरह हैं।",rom:"mere lie āp sab bhī ek dīye kī tarah haiṁ.",ja:"私にとって、皆さんもランプの明かりのような存在です。",note:"お祭りのたとえを、仲間への感謝につなげる。"},
   {hi:"यह दिवाली आपके घर में रोशनी और ख़ुशियाँ लाए।",rom:"yah divālī āpke ghar meṁ roshnī aur khushiyāṁ lāe.",ja:"このディワリが、皆さんの家に光と幸せを運びますように。",note:"願いの -ए。来週の文法だが、決まり文句として覚える。"}
  ],
  model:{title:"ディワリの時期のオンラインの集まりでのスピーチ", time:"2分30秒", note:"ディワリの時期の例です。ホーリーのときは होली मुबारक हो! で始め、色の話に入れかえましょう。", lines:[
   {hi:"नमस्ते दोस्तों! आप सब को दिवाली की हार्दिक शुभकामनाएँ!",rom:"namaste dostoṁ! āp sab ko divālī kī hārdik shubhkāmnāeṁ!",ja:"皆さん、こんにちは！心からディワリおめでとうございます！"},
   {hi:"आज इस ऑनलाइन मीटिंग में आपसे मिलकर मुझे बहुत ख़ुशी हो रही है।",rom:"āj is onlāin mīṭing meṁ āpse milkar mujhe bahut khushī ho rahī hai.",ja:"今日、このオンラインの集まりで皆さんに会えて、とてもうれしいです。"},
   {hi:"मैं जापान से हूँ, लेकिन मैं आप सब से भारत के त्योहारों के बारे में सीख रहा हूँ।",rom:"maiṁ Jāpān se hūṁ, lekin maiṁ āp sab se Bhārat ke tyohāroṁ ke bāre meṁ sīkh rahā hūṁ.",ja:"私は日本から来ていますが、皆さんからインドのお祭りのことを学んでいます。"},
   {hi:"दिवाली रोशनी का त्योहार है।",rom:"divālī roshnī kā tyohār hai.",ja:"ディワリは光のお祭りです。"},
   {hi:"दिवाली से पहले लोग घर की सफ़ाई करते हैं।",rom:"divālī se pahle log ghar kī safāī karte haiṁ.",ja:"ディワリの前には、家の掃除をします。"},
   {hi:"दिवाली पर लोग दीये जलाते हैं, रंगोली बनाते हैं और घर सजाते हैं।",rom:"divālī par log dīye jalāte haiṁ, rangolī banāte haiṁ aur ghar sajāte haiṁ.",ja:"ディワリには、ランプをともし、ランゴーリーを描き、家を飾ります。"},
   {hi:"लोग पूजा करते हैं और परिवार के साथ मिठाई खाते हैं।",rom:"log pūjā karte haiṁ aur parivār ke sāth miṭhāī khāte haiṁ.",ja:"お祈りをして、家族と一緒にお菓子を食べます。"},
   {hi:"दोस्तों और रिश्तेदारों को मिठाई और तोहफ़े भी देते हैं।",rom:"dostoṁ aur rishtedāroṁ ko miṭhāī aur tohfe bhī dete haiṁ.",ja:"友だちや親戚に、お菓子や贈り物も渡します。"},
   {hi:"जापान में दिवाली नहीं होती, लेकिन हमारा नया साल थोड़ा ऐसा ही है।",rom:"Jāpān meṁ divālī nahīṁ hotī, lekin hamārā nayā sāl thoṛā aisā hī hai.",ja:"日本にディワリはありませんが、日本のお正月は少し似ています。"},
   {hi:"नए साल से पहले जापान में भी लोग पूरे घर की सफ़ाई करते हैं।",rom:"nae sāl se pahle Jāpān meṁ bhī log pūre ghar kī safāī karte haiṁ.",ja:"お正月の前には、日本でも家じゅうを掃除します。"},
   {hi:"नए साल पर लोग मंदिर जाते हैं और परिवार के साथ ख़ास खाना खाते हैं।",rom:"nae sāl par log mandir jāte haiṁ aur parivār ke sāth khās khānā khāte haiṁ.",ja:"お正月には神社やお寺に行き、家族と特別な料理を食べます。"},
   {hi:"मुझे लगता है, दोनों देशों में त्योहार का दिल एक ही है: नई शुरुआत और परिवार।",rom:"mujhe lagtā hai, donoṁ deshoṁ meṁ tyohār kā dil ek hī hai: naī shuruāt aur parivār.",ja:"2つの国のお祭りの心は同じだと思います。新しい始まりと、家族です。"},
   {hi:"दिवाली अँधेरे से रोशनी की ओर जाने का त्योहार है।",rom:"divālī aṁdhere se roshnī kī or jāne kā tyohār hai.",ja:"ディワリは、暗やみから光へ向かうお祭りです。"},
   {hi:"मेरे लिए आप सब भी एक दीये की तरह हैं।",rom:"mere lie āp sab bhī ek dīye kī tarah haiṁ.",ja:"私にとって、皆さんもランプの明かりのような存在です。"},
   {hi:"आपके संदेश और आपकी मुस्कान से मुझे बहुत हिम्मत मिलती है।",rom:"āpke sandesh aur āpkī muskān se mujhe bahut himmat miltī hai.",ja:"皆さんのメッセージと笑顔から、いつも元気をもらっています。"},
   {hi:"इस साल हमने साथ में बहुत कुछ सीखा। आप सब का दिल से धन्यवाद।",rom:"is sāl hamne sāth meṁ bahut kuchh sīkhā. āp sab kā dil se dhanyavād.",ja:"今年は一緒にたくさんのことを学びました。皆さん、心からありがとうございます。"},
   {hi:"यह दिवाली आपके घर में रोशनी और ख़ुशियाँ लाए।",rom:"yah divālī āpke ghar meṁ roshnī aur khushiyāṁ lāe.",ja:"このディワリが、皆さんの家に光と幸せを運びますように。"},
   {hi:"एक बार फिर, शुभ दीपावली! धन्यवाद।",rom:"ek bār phir, shubh dīpāvalī! dhanyavād.",ja:"もう一度、ディワリおめでとうございます！ありがとうございました。"}
  ]},
  task:"インドの仲間のオンラインの集まりで、2分30秒のスピーチをする。お祭りのあいさつで始め、インドの行事を3文、日本の似た行事を2文で説明し、仲間への感謝と願いで締める。勧誘・宣伝は入れない。",
  taskEn:"Give a two-and-a-half-minute speech at an online gathering of your friends in India. Open with a festival greeting, describe the Indian festival in three sentences and a similar Japanese custom in two, and close with thanks and good wishes. Do not include any sales or recruiting talk.",
  qa:[
   {q:"जापान में कौन-सा त्योहार दिवाली जैसा है?",qRom:"Jāpān meṁ kaun-sā tyohār divālī jaisā hai?",a:"नया साल थोड़ा दिवाली जैसा है। लोग घर साफ़ करते हैं और परिवार के साथ रहते हैं।",aRom:"nayā sāl thoṛā divālī jaisā hai. log ghar sāf karte haiṁ aur parivār ke sāth rahte haiṁ.",ja:"質問：日本では、どのお祭りがディワリに似ていますか。／答え：お正月が少し似ています。家を掃除して、家族と過ごします。"},
   {q:"क्या जापान में भी त्योहार पर लोग तोहफ़े देते हैं?",qRom:"kyā Jāpān meṁ bhī tyohār par log tohfe dete haiṁ?",a:"जी हाँ, जापान में भी लोग तोहफ़े देते हैं। नए साल पर बच्चों को पैसे भी देते हैं।",aRom:"jī hāṁ, Jāpān meṁ bhī log tohfe dete haiṁ. nae sāl par bachchoṁ ko paise bhī dete haiṁ.",ja:"質問：日本でも、お祭りのときに贈り物をしますか。／答え：はい、日本でも贈り物をします。お正月には子どもにお金（お年玉）もあげます。"},
   {q:"आप होली पर क्या कहेंगे?",qRom:"āp holī par kyā kaheṁge?",a:"मैं कहूँगा: होली मुबारक हो! और सब को रंग लगाऊँगा।",aRom:"maiṁ kahūṁgā: holī mubārak ho! aur sab ko rang lagāūṁgā.",ja:"質問：ホーリーのときは何と言いますか。／答え：「ハッピーホーリー！」と言って、みんなに色をつけます。"}
  ],
  check:[
   "最初の1文でお祭りのあいさつをはっきり言えたか",
   "पर（〜のときに）と -ते हैं で、行事を一般の現在形で説明できたか",
   "インドと日本の似ているところを1つ見つけて言えたか",
   "お祭りの意味を、仲間への感謝につなげられたか",
   "勧誘や宣伝を入れず、感謝と願いだけで締めたか"
  ],
  slide:"ディワリのランプ（दीया）と日本のお正月の写真を左右に並べ、真ん中に「नई शुरुआत और परिवार」と1行だけ書きます。"},

 {week:31, level:"A2", length:"3分", title:"お祝いと感謝のスピーチ",
  skill:"仲間の集まりで、お祝いと感謝を名前を挙げて伝え、願いの形 -ए／-एँ で温かく締める3分のスピーチができるようになる。",
  lesson:[
   "お祝いのスピーチは「おめでとう → 思い出と感謝 → 自分が学んだこと → 願い」の順が基本です。ヒンディー語では最初に … की बहुत-बहुत बधाई! や … मुबारक हो! とはっきり言うと、聞き手はすぐにお祝いの場だとわかります。",
   "感謝は、名前を挙げて具体的に言うのがインド流です。नेहा जी, … के लिए आपका बहुत-बहुत शुक्रिया。「何に」ありがとうなのかを1つずつ言うと、言われた人も、聞いている人も心が温かくなります。मैं आप सब का दिल से आभारी हूँ（皆さんに心から感謝しています）は、全員へのお礼の決まり文句です。",
   "今週の文法、願いの形 -ए は、スピーチの締めにぴったりです。भगवान आपको ख़ुश रखे（神さまがあなたを幸せにしてくださいますように）、आपको कामयाबी मिले（成功しますように）。主語が आप・आप सब のときは -एँ になります：आप हमेशा स्वस्थ रहें।",
   "仲間の前のスピーチでは、勧誘や「得をする」話は入れません。自分が助けてもらったこと、学んだことを正直に話すほど、聞き手との距離は近くなります。3分は長く感じますが、短い文を重ねれば十分に話せます。"
  ],
  structure:[
   {hi:"बधाई",rom:"badhāī",ja:"おめでとう"},
   {hi:"यादें और धन्यवाद",rom:"yādeṁ aur dhanyavād",ja:"思い出と感謝（名前を挙げて）"},
   {hi:"मेरी सीख",rom:"merī sīkh",ja:"自分が学んだこと（3つ）"},
   {hi:"शुभकामनाएँ",rom:"shubhkāmnāeṁ",ja:"願い（-ए／-एँ）"},
   {hi:"समापन",rom:"samāpan",ja:"拍手と締め"}
  ],
  phrases:[
   {hi:"आप सब को ग्रुप की पहली सालगिरह की बहुत-बहुत बधाई!",rom:"āp sab ko grup kī pahlī sālgirah kī bahut-bahut badhāī!",ja:"皆さん、グループの1周年、本当におめでとうございます！",note:"… की बधाई で「〜おめでとう」。最初に言い切る。"},
   {hi:"जन्मदिन मुबारक हो, अर्जुन जी!",rom:"janmdin mubārak ho, Arjun jī!",ja:"アルジュンさん、お誕生日おめでとうございます！",note:"मुबारक हो は形が変わらない。"},
   {hi:"नेहा जी, मदद के लिए आपका बहुत-बहुत शुक्रिया।",rom:"Nehā jī, madad ke lie āpkā bahut-bahut shukriyā.",ja:"ネハさん、助けてくださって本当にありがとうございます。",note:"名前＋何に＋感謝、の順で具体的に。"},
   {hi:"मैं आप सब का दिल से आभारी हूँ।",rom:"maiṁ āp sab kā dil se ābhārī hūṁ.",ja:"皆さんに心から感謝しています。",note:"आभारी は形が変わらない。全員へのお礼。"},
   {hi:"इस साल मैंने आपसे तीन बातें सीखीं।",rom:"is sāl maiṁne āpse tīn bāteṁ sīkhīṁ.",ja:"今年、皆さんから3つのことを学びました。",note:"बातें（女・複数）に合わせて सीखीं。"},
   {hi:"भगवान आपको हमेशा ख़ुश रखे।",rom:"bhagvān āpko hameshā khush rakhe.",ja:"いつまでもお幸せでありますように。",note:"願いの -ए。主語は भगवान（3人称）。"},
   {hi:"आप सब हमेशा स्वस्थ रहें।",rom:"āp sab hameshā svasth raheṁ.",ja:"皆さんが、いつも元気でいられますように。",note:"主語が आप なら -एँ。"},
   {hi:"आपको अपने हर काम में कामयाबी मिले।",rom:"āpko apne har kām meṁ kāmyābī mile.",ja:"皆さんのすべてのお仕事がうまくいきますように。",note:"को＋मिले の形で「〜に…がありますように」。"},
   {hi:"हमारी दोस्ती ऐसे ही बनी रहे।",rom:"hamārī dostī aise hī banī rahe.",ja:"私たちの友情が、このままずっと続きますように。",note:"बना रहना＝ずっと続く。दोस्ती（女）なので बनी。"},
   {hi:"चलिए, सब मिलकर ताली बजाते हैं!",rom:"chalie, sab milkar tālī bajāte haiṁ!",ja:"では、みんなで拍手しましょう！",note:"スピーチの最後を明るく終える合図。"}
  ],
  model:{title:"グループの1周年のお祝いと感謝のスピーチ", time:"3分", note:"名前と場面は練習用の例です。自分の仲間の名前と思い出に入れかえましょう。", lines:[
   {hi:"नमस्ते दोस्तों! आज हमारे ग्रुप की पहली सालगिरह है।",rom:"namaste dostoṁ! āj hamāre grup kī pahlī sālgirah hai.",ja:"皆さん、こんにちは！今日は私たちのグループの1周年です。"},
   {hi:"आप सब को बहुत-बहुत बधाई!",rom:"āp sab ko bahut-bahut badhāī!",ja:"皆さん、本当におめでとうございます！"},
   {hi:"मुझे आज कुछ शब्द कहने का मौक़ा मिला। इसके लिए धन्यवाद।",rom:"mujhe āj kuchh shabd kahne kā mauqā milā. iske lie dhanyavād.",ja:"今日はひとことお話しする機会をいただき、ありがとうございます。"},
   {hi:"कुछ महीने पहले मैं हिंदी में सिर्फ़ नमस्ते कह सकता था।",rom:"kuchh mahīne pahle maiṁ hindī meṁ sirf namaste kah saktā thā.",ja:"数か月前、私はヒンディー語で「ナマステ」しか言えませんでした。"},
   {hi:"आज मैं आपके सामने हिंदी में बोल रहा हूँ। यह आप सब की वजह से है।",rom:"āj maiṁ āpke sāmne hindī meṁ bol rahā hūṁ. yah āp sab kī vajah se hai.",ja:"今日は皆さんの前でヒンディー語で話しています。皆さんのおかげです。"},
   {hi:"नेहा जी, आपने हमेशा मुझे धीरे-धीरे और प्यार से समझाया।",rom:"Nehā jī, āpne hameshā mujhe dhīre-dhīre aur pyār se samjhāyā.",ja:"ネハさん、いつもゆっくり、やさしく教えてくださいました。"},
   {hi:"आपकी मदद के लिए आपका बहुत-बहुत शुक्रिया।",rom:"āpkī madad ke lie āpkā bahut-bahut shukriyā.",ja:"助けてくださって、本当にありがとうございます。"},
   {hi:"अर्जुन जी, भारत में आप मुझे हमेशा अपने घर बुलाते हैं।",rom:"Arjun jī, Bhārat meṁ āp mujhe hameshā apne ghar bulāte haiṁ.",ja:"アルジュンさん、インドではいつもご自宅に招いてくださいます。"},
   {hi:"आपके घर का खाना और आपकी मेहमाननवाज़ी मैं कभी नहीं भूलूँगा।",rom:"āpke ghar kā khānā aur āpkī mehmānnavāzī maiṁ kabhī nahīṁ bhūlūṁgā.",ja:"ご家庭の料理とおもてなしは、決して忘れません。"},
   {hi:"मैं आप सब का दिल से आभारी हूँ।",rom:"maiṁ āp sab kā dil se ābhārī hūṁ.",ja:"皆さんに心から感謝しています。"},
   {hi:"इस साल मैंने आपसे तीन बातें सीखीं।",rom:"is sāl maiṁne āpse tīn bāteṁ sīkhīṁ.",ja:"今年、皆さんから3つのことを学びました。"},
   {hi:"पहली, हर दिन थोड़ा-थोड़ा सीखना।",rom:"pahlī, har din thoṛā-thoṛā sīkhnā.",ja:"1つ目は、毎日少しずつ学ぶこと。"},
   {hi:"दूसरी, एक-दूसरे की मदद करना।",rom:"dūsrī, ek-dūsre kī madad karnā.",ja:"2つ目は、お互いに助け合うこと。"},
   {hi:"तीसरी, हर छोटी ख़ुशी को साथ मिलकर मनाना।",rom:"tīsrī, har chhoṭī khushī ko sāth milkar manānā.",ja:"3つ目は、小さな喜びもみんなで一緒にお祝いすること。"},
   {hi:"जापान में अपने काम में भी मेरा एक नियम है: सामने वाले इंसान के लिए पूरी कोशिश करना।",rom:"Jāpān meṁ apne kām meṁ bhī merā ek niyam hai: sāmne vāle insān ke lie pūrī koshish karnā.",ja:"日本での仕事でも、私には1つの決まりがあります。目の前の人に全力を尽くすことです。"},
   {hi:"यहाँ आप सब भी हर दिन यही करते हैं।",rom:"yahāṁ āp sab bhī har din yahī karte haiṁ.",ja:"ここにいる皆さんも、毎日それをしています。"},
   {hi:"अब कुछ शुभकामनाएँ।",rom:"ab kuchh shubhkāmnāeṁ.",ja:"では、願いをこめて。"},
   {hi:"आप सब हमेशा स्वस्थ रहें।",rom:"āp sab hameshā svasth raheṁ.",ja:"皆さんが、いつも元気でいられますように。"},
   {hi:"भगवान आपके परिवार को हमेशा ख़ुश रखे।",rom:"bhagvān āpke parivār ko hameshā khush rakhe.",ja:"皆さんのご家族が、いつも幸せでありますように。"},
   {hi:"आपको अपने हर काम में कामयाबी मिले।",rom:"āpko apne har kām meṁ kāmyābī mile.",ja:"皆さんのすべてのお仕事がうまくいきますように。"},
   {hi:"और हमारी दोस्ती ऐसे ही बनी रहे।",rom:"aur hamārī dostī aise hī banī rahe.",ja:"そして、私たちの友情が、このままずっと続きますように。"},
   {hi:"चलिए, सब मिलकर ताली बजाते हैं! बहुत-बहुत धन्यवाद।",rom:"chalie, sab milkar tālī bajāte haiṁ! bahut-bahut dhanyavād.",ja:"では、みんなで拍手しましょう！本当にありがとうございました。"}
  ]},
  task:"インドの仲間の集まりで、3分のお祝いと感謝のスピーチをする。最初におめでとうを言い、2人の名前を挙げて具体的にお礼を言い、学んだことを3つ話し、願いの形 -ए／-एँ を3つ使って締める。勧誘・宣伝は入れない。",
  taskEn:"Give a three-minute speech of congratulations and thanks at a gathering of your friends in India. Open with congratulations, thank two people by name for specific things, share three things you learned, and close with three good wishes. Do not include any sales or recruiting talk.",
  qa:[
   {q:"आप हिंदी कब से सीख रहे हैं?",qRom:"āp hindī kab se sīkh rahe haiṁ?",a:"मैं कुछ महीनों से हिंदी सीख रहा हूँ। हर दिन थोड़ा-थोड़ा पढ़ता हूँ।",aRom:"maiṁ kuchh mahīnoṁ se hindī sīkh rahā hūṁ. har din thoṛā-thoṛā paṛhtā hūṁ.",ja:"質問：いつからヒンディー語を勉強していますか。／答え：数か月前から勉強しています。毎日少しずつ学んでいます。"},
   {q:"जापान में जन्मदिन पर लोग क्या कहते हैं?",qRom:"Jāpān meṁ janmdin par log kyā kahte haiṁ?",a:"जापानी में ‘ओतानजोबी ओमेदेतो’ कहते हैं। इसका मतलब है, जन्मदिन मुबारक हो।",aRom:"jāpānī meṁ ‘otānjobī omedeto’ kahte haiṁ. iskā matlab hai, janmdin mubārak ho.",ja:"質問：日本では誕生日に何と言いますか。／答え：日本語で「お誕生日おめでとう」と言います。「जन्मदिन मुबारक हो」という意味です。"},
   {q:"आपके लिए दोस्ती का मतलब क्या है?",qRom:"āpke lie dostī kā matlab kyā hai?",a:"मेरे लिए दोस्ती का मतलब है, मुश्किल समय में साथ रहना।",aRom:"mere lie dostī kā matlab hai, mushkil samay meṁ sāth rahnā.",ja:"質問：あなたにとって友情とは何ですか。／答え：私にとって友情とは、大変なときにそばにいることです。"}
  ],
  check:[
   "最初の2文で、何のお祝いかをはっきり言えたか",
   "名前を挙げて、何に感謝しているかを具体的に言えたか",
   "学んだことを पहली・दूसरी・तीसरी で3つに分けられたか",
   "願いの形（रखे・मिले・रहें）を3つ以上使えたか",
   "勧誘や宣伝を入れず、感謝と学びだけで話せたか"
  ],
  slide:"グループの集合写真を1枚、大きく。下に「बहुत-बहुत बधाई!」と1行だけ。文字より写真で気持ちを伝えます。"},

 {week:32, level:"A2", length:"3分", title:"オンライン（WhatsApp・ビデオ会議）で案内する",
  skill:"ビデオ会議の始めと終わりに、音声・画面・資料の確認を英語まじりのヒンディー語で案内し、WhatsApp での連絡につなげられるようになる。",
  lesson:[
   "インドのビジネスの会話では、英語の単語をそのまま混ぜるのがふつうです。「シェアする」は शेयर करना、「ミュートにする」は म्यूट करना、「参加する」は जॉइन करना。英語の単語＋करना／होना で、たいていの操作を言えます。",
   "ビデオ会議の最初の1分は「確認」の時間です。क्या मेरी आवाज़ आ रही है?（私の声は聞こえていますか）、क्या स्लाइड दिख रही है?（スライドは見えていますか）。進行形で聞くのが自然です。うなずきが見えにくいので、必ず声に出して確かめましょう。",
   "WhatsApp はインドのビジネスの大事な道具です。資料やリンクは मैं व्हाट्सऐप ग्रुप में शेयर कर दूँगा（WhatsApp のグループでシェアしておきます）と言い、会議の後に必ず送ります。チャットではローマ字のヒンディー語（ok ji, thik h）もよく使われますが、取引先には जी をつけ、यार は使いません。",
   "音が途切れたときは、黙らずに何が起きたかを言います。आवाज़ थोड़ी कट रही है（声が少し途切れています）、मैं फिर से जॉइन करता हूँ（入り直します）。最後に「次はいつ・何で連絡するか」を言って終わると、相手は安心します。細かい条件は英語のメールで、と添えるのも親切です。"
  ],
  structure:[
   {hi:"आवाज़ और स्क्रीन की जाँच",rom:"āvāz aur skrīn kī jāṁch",ja:"音声と画面の確認"},
   {hi:"अभिवादन",rom:"abhivādan",ja:"あいさつと自己紹介"},
   {hi:"आज का एजेंडा",rom:"āj kā ejenḍā",ja:"今日の流れ（3つ）"},
   {hi:"मुख्य बात",rom:"mukhya bāt",ja:"本題（途中のトラブルの立て直しも）"},
   {hi:"व्हाट्सऐप पर अगला क़दम",rom:"vhāṭsaip par aglā qadam",ja:"WhatsApp での次の一歩"}
  ],
  phrases:[
   {hi:"क्या मेरी आवाज़ आ रही है?",rom:"kyā merī āvāz ā rahī hai?",ja:"私の声は聞こえていますか。",note:"直訳は「私の声は来ていますか」。会議の最初の決まり文句。"},
   {hi:"मैं अपनी स्क्रीन शेयर कर रहा हूँ। क्या स्लाइड दिख रही है?",rom:"maiṁ apnī skrīn sheyar kar rahā hūṁ. kyā slāiḍ dikh rahī hai?",ja:"画面を共有しています。スライドは見えていますか。",note:"स्क्रीन・स्लाइड は女性名詞なので दिख रही है。"},
   {hi:"कृपया अपना माइक म्यूट रखिए।",rom:"kripayā apnā māik myūṭ rakhie.",ja:"マイクはミュートにしておいてください。",note:"英語の単語＋रखना／करना。"},
   {hi:"सवाल चैट में लिख दीजिए।",rom:"savāl chaiṭ meṁ likh dījie.",ja:"質問はチャットに書いておいてください。",note:"複合動詞 लिख दीजिए でやわらかいお願いに。"},
   {hi:"आवाज़ थोड़ी कट रही है। मैं फिर से जॉइन करता हूँ।",rom:"āvāz thoṛī kaṭ rahī hai. maiṁ phir se join kartā hūṁ.",ja:"声が少し途切れています。入り直します。",note:"黙らずに、何が起きたかを言う。"},
   {hi:"कोई टेंशन नहीं, हम यहीं से शुरू करते हैं।",rom:"koī ṭenshan nahīṁ, ham yahīṁ se shurū karte haiṁ.",ja:"大丈夫です、ここから続けましょう。",note:"टेंशन は英語から。場を落ち着かせる言い方。"},
   {hi:"मैंने मीटिंग का लिंक व्हाट्सऐप पर भेज दिया।",rom:"maiṁne mīṭing kā link vhāṭsaip par bhej diyā.",ja:"会議のリンクは WhatsApp で送っておきました。",note:"भेज दिया＝送っておいた（複合動詞）。"},
   {hi:"मीटिंग के बाद मैं स्लाइड्स व्हाट्सऐप ग्रुप में शेयर कर दूँगा।",rom:"mīṭing ke bād maiṁ slāiḍs vhāṭsaip grup meṁ sheyar kar dūṁgā.",ja:"会議のあと、スライドを WhatsApp のグループでシェアしておきます。",note:"कर दूँगा＝しておきます。相手を安心させる約束。"},
   {hi:"डिटेल्स हम अंग्रेज़ी में ईमेल से भेज देंगे।",rom:"ḍiṭels ham angrezī meṁ īmel se bhej deṁge.",ja:"細かい点は、英語のメールでお送りします。",note:"条件の話は英語へ切り替えてよい。"},
   {hi:"ठीक है जी, फिर अगले हफ़्ते मिलते हैं।",rom:"ṭhīk hai jī, phir agle hafte milte haiṁ.",ja:"わかりました、では来週お会いしましょう。",note:"取引先には जी をつける。यार は使わない。"}
  ],
  model:{title:"取引先とのビデオ会議の進行（始め・途中・終わり）", time:"3分", note:"時間・曜日・提案の中身は練習用の例です。会議に合わせて入れかえましょう。", lines:[
   {hi:"नमस्ते प्रिया जी, नमस्ते आप सब को। क्या मेरी आवाज़ आ रही है?",rom:"namaste Priyā jī, namaste āp sab ko. kyā merī āvāz ā rahī hai?",ja:"プリヤさん、皆さん、こんにちは。私の声は聞こえていますか。"},
   {hi:"अच्छा, आवाज़ ठीक है। धन्यवाद।",rom:"achchhā, āvāz ṭhīk hai. dhanyavād.",ja:"よかった、音は大丈夫ですね。ありがとうございます。"},
   {hi:"मैं अपनी स्क्रीन शेयर कर रहा हूँ। क्या स्लाइड दिख रही है?",rom:"maiṁ apnī skrīn sheyar kar rahā hūṁ. kyā slāiḍ dikh rahī hai?",ja:"画面を共有しています。スライドは見えていますか。"},
   {hi:"कृपया अपना माइक म्यूट रखिए। सवाल चैट में लिख दीजिए।",rom:"kripayā apnā māik myūṭ rakhie. savāl chaiṭ meṁ likh dījie.",ja:"マイクはミュートにしておいてください。質問はチャットに書いておいてください。"},
   {hi:"मेरा नाम आकिहिरो इवाता है। मैं जापान के एहिमे से जॉइन कर रहा हूँ।",rom:"merā nām Ākihiro Ivātā hai. maiṁ Jāpān ke Ehime se join kar rahā hūṁ.",ja:"岩田章弘です。日本の愛媛から参加しています。"},
   {hi:"यहाँ अभी शाम है, और दिल्ली में दोपहर है, है ना?",rom:"yahāṁ abhī shām hai, aur Dillī meṁ dopahar hai, hai nā?",ja:"こちらは今、夕方です。デリーはお昼すぎですよね？"},
   {hi:"आज मैं बीस मिनट बोलूँगा और फिर दस मिनट सवाल-जवाब।",rom:"āj maiṁ bīs minaṭ bolūṁgā aur phir das minaṭ savāl-javāb.",ja:"今日は20分お話しして、そのあと10分、質疑応答です。"},
   {hi:"आज का एजेंडा तीन हिस्सों में है।",rom:"āj kā ejenḍā tīn hissoṁ meṁ hai.",ja:"今日の流れは3つに分かれています。"},
   {hi:"पहला, ओमोतेनाशी क्या है। दूसरा, आपके होटल के लिए तीन आइडिया। तीसरा, अगला क़दम।",rom:"pahlā, omotenāshī kyā hai. dūsrā, āpke hoṭal ke lie tīn āiḍiyā. tīsrā, aglā qadam.",ja:"1つ目、おもてなしとは何か。2つ目、皆さんのホテルのための3つのアイデア。3つ目、次の一歩です。"},
   {hi:"चलिए, पहली स्लाइड देखते हैं।",rom:"chalie, pahlī slāiḍ dekhte haiṁ.",ja:"では、1枚目のスライドを見ましょう。"},
   {hi:"ओमोतेनाशी का मतलब है, मेहमान के कहने से पहले उनकी ज़रूरत समझना।",rom:"omotenāshī kā matlab hai, mehmān ke kahne se pahle unkī zarūrat samajhnā.",ja:"おもてなしとは、お客様が言う前に、必要なことを察することです。"},
   {hi:"अब दूसरी स्लाइड। यहाँ तीन आइडिया हैं: नाम से स्वागत, खाने से पहले छोटा सवाल, और कमरे में चप्पल।",rom:"ab dūsrī slāiḍ. yahāṁ tīn āiḍiyā haiṁ: nām se svāgat, khāne se pahle chhoṭā savāl, aur kamre meṁ chappal.",ja:"次は2枚目です。アイデアは3つ。名前でお迎えする、食事の前に短く聞く、お部屋にスリッパ、です。"},
   {hi:"अरे, आवाज़ थोड़ी कट रही है? एक मिनट, मैं फिर से जॉइन करता हूँ।",rom:"are, āvāz thoṛī kaṭ rahī hai? ek minaṭ, maiṁ phir se join kartā hūṁ.",ja:"あれ、声が少し途切れていますか。ちょっと待ってください、入り直します。"},
   {hi:"सॉरी, अब ठीक है? कोई टेंशन नहीं, हम यहीं से शुरू करते हैं।",rom:"sorī, ab ṭhīk hai? koī ṭenshan nahīṁ, ham yahīṁ se shurū karte haiṁ.",ja:"すみません、今は大丈夫ですか。大丈夫です、ここから続けましょう。"},
   {hi:"ये तीनों आइडिया छोटे हैं। आपकी टीम आसानी से शुरू कर सकती है।",rom:"ye tīnoṁ āiḍiyā chhoṭe haiṁ. āpkī ṭīm āsānī se shurū kar saktī hai.",ja:"この3つのアイデアは小さなことです。チームの皆さんが、すぐに始められます。"},
   {hi:"अब तीसरी स्लाइड, अगला क़दम।",rom:"ab tīsrī slāiḍ, aglā qadam.",ja:"では3枚目、次の一歩です。"},
   {hi:"मीटिंग के बाद मैं ये स्लाइड्स व्हाट्सऐप ग्रुप में शेयर कर दूँगा।",rom:"mīṭing ke bād maiṁ ye slāiḍs vhāṭsaip grup meṁ sheyar kar dūṁgā.",ja:"会議のあと、このスライドを WhatsApp のグループでシェアしておきます。"},
   {hi:"डिटेल्स और क़ीमत की बात हम अंग्रेज़ी में ईमेल से कर सकते हैं।",rom:"ḍiṭels aur qīmat kī bāt ham angrezī meṁ īmel se kar sakte haiṁ.",ja:"細かい点と料金のお話は、英語のメールでできます。"},
   {hi:"आप अपनी टीम से बात करके व्हाट्सऐप पर बताइएगा।",rom:"āp apnī ṭīm se bāt karke vhāṭsaip par batāiegā.",ja:"チームの皆さんと話し合ってから、WhatsApp でお知らせくださいね。"},
   {hi:"अब सवाल-जवाब का समय है। चैट में या माइक ऑन करके पूछिए।",rom:"ab savāl-javāb kā samay hai. chaiṭ meṁ yā māik on karke pūchhie.",ja:"では質疑応答の時間です。チャットか、マイクをオンにしてご質問ください。"},
   {hi:"आज जॉइन करने के लिए आप सब का बहुत-बहुत शुक्रिया।",rom:"āj join karne ke lie āp sab kā bahut-bahut shukriyā.",ja:"今日はご参加いただき、本当にありがとうございました。"},
   {hi:"ठीक है जी, फिर अगले हफ़्ते मिलते हैं। नमस्ते!",rom:"ṭhīk hai jī, phir agle hafte milte haiṁ. namaste!",ja:"それでは、また来週お会いしましょう。失礼します！"}
  ]},
  task:"インドの取引先とのビデオ会議で、3分の案内をする。音と画面の確認、ミュートと質問のしかたのお願い、今日の流れ、途中で音が途切れたときの立て直し、WhatsApp で資料を送る約束までを入れる。",
  taskEn:"Run the first and last parts of a three-minute video meeting with an Indian partner company. Check the sound and screen, ask people to mute and use the chat, give the agenda, recover when your audio cuts out, and promise to share the slides in the WhatsApp group.",
  qa:[
   {q:"क्या आप स्लाइड्स ईमेल पर भी भेज सकते हैं?",qRom:"kyā āp slāiḍs īmel par bhī bhej sakte haiṁ?",a:"जी हाँ, बिल्कुल। मैं आज ही ईमेल पर भी भेज दूँगा।",aRom:"jī hāṁ, bilkul. maiṁ āj hī īmel par bhī bhej dūṁgā.",ja:"質問：スライドをメールでも送っていただけますか。／答え：はい、もちろんです。今日中にメールでもお送りします。"},
   {q:"अगली मीटिंग कब होगी?",qRom:"aglī mīṭing kab hogī?",a:"आप लोगों के हिसाब से तय करेंगे। मैं व्हाट्सऐप पर दो-तीन तारीख़ें भेज दूँगा।",aRom:"āp logoṁ ke hisāb se tay kareṁge. maiṁ vhāṭsaip par do-tīn tārīkheṁ bhej dūṁgā.",ja:"質問：次の会議はいつですか。／答え：皆さんのご都合に合わせて決めます。WhatsApp で候補の日を2つか3つお送りします。"},
   {q:"आख़िरी बात फिर से बताइए, आवाज़ साफ़ नहीं आई।",qRom:"ākhirī bāt phir se batāie, āvāz sāf nahīṁ āī.",a:"ज़रूर। मैंने कहा: मीटिंग के बाद स्लाइड्स व्हाट्सऐप ग्रुप में शेयर कर दूँगा।",aRom:"zarūr. maiṁne kahā: mīṭing ke bād slāiḍs vhāṭsaip grup meṁ sheyar kar dūṁgā.",ja:"質問：最後の点をもう一度お願いします。声がよく聞こえませんでした。／答え：もちろんです。「会議のあと、スライドを WhatsApp のグループでシェアします」と言いました。"}
  ],
  check:[
   "最初に、声と画面の2つを声に出して確かめたか",
   "英語の単語＋करना（शेयर करना・जॉइन करना）を自然に使えたか",
   "音が途切れたとき、黙らずに何が起きたかを言えたか",
   "取引先に जी をつけ、यार を使わなかったか",
   "最後に「何を・どこに・いつ送るか」を約束できたか"
  ],
  slide:"1枚目に「आज का एजेंडा」と3つの項目だけ。画面が小さいスマートフォンでも読めるように、文字は大きく、1枚に1つの話だけにします。"},

 {week:33, level:"A2", length:"3分", title:"「もし〜なら」で提案する",
  skill:"अगर … तो … と接続法（करें・आऊँ）を使って、相手の都合に合わせた2つの案を出し、次の一歩を相談できるようになる。",
  lesson:[
   "提案を「これをしてください」と1つだけ出すと、相手は「はい」か「いいえ」しか選べません。अगर … तो …（もし〜なら、〜）で条件ごとに案を出すと、相手が自分で選べるので、話がぐっと進みやすくなります。",
   "अगर のあとは現在形も未来形も使えます。अगर आपके पास समय है, तो …（もしお時間があれば）、अगर ट्रायल अच्छा रहेगा, तो …（もし試しがうまくいけば）。तो のあとに自分の申し出を言います。日本語の「〜なら、〜」と順番は同じです。",
   "接続法 -ऊँ／-एँ は「〜しましょうか」「〜かもしれません」のやわらかい形です。हम पहले एक छोटा ट्रायल करें?（まず小さく試してみましょうか）、शायद मैं अगले महीने दिल्ली आऊँ（来月デリーにうかがうかもしれません）。押しつけずに提案できるので、商談の冒頭にぴったりです。",
   "आप चाहें तो（よろしければ）は、ていねいな提案でいちばん便利な言い方です。最後は आपके लिए कौन-सा विकल्प बेहतर है?（どちらの案がよろしいですか）と聞いて、相手に選んでもらいましょう。料金や契約の細かい話は、英語に切り替えてかまいません。"
  ],
  structure:[
   {hi:"अभिवादन",rom:"abhivādan",ja:"あいさつと感謝"},
   {hi:"पिछली बात",rom:"pichhlī bāt",ja:"前回の話のふり返り"},
   {hi:"दो विकल्प",rom:"do vikalp",ja:"2つの案（अगर … तो …）"},
   {hi:"एक जैसी बात",rom:"ek jaisī bāt",ja:"どちらの案でも変わらないこと"},
   {hi:"आपकी पसंद",rom:"āpkī pasand",ja:"どちらがよいか聞いて、次の一歩へ"}
  ],
  phrases:[
   {hi:"अगर आपके पास दस मिनट हैं, तो मैं दो विकल्प दिखाना चाहता हूँ।",rom:"agar āpke pās das minaṭ haiṁ, to maiṁ do vikalp dikhānā chāhtā hūṁ.",ja:"もし10分いただければ、2つの案をお見せしたいと思います。",note:"本題に入る前に、時間の許しをもらう。"},
   {hi:"आप चाहें तो हम पहले एक छोटा ट्रायल करें?",rom:"āp chāheṁ to ham pahle ek chhoṭā ṭrāyal kareṁ?",ja:"よろしければ、まず小さく試してみましょうか。",note:"चाहें तो＋接続法 करें? で、押しつけない提案。"},
   {hi:"अगर ट्रायल अच्छा रहेगा, तो हम आगे बढ़ेंगे।",rom:"agar ṭrāyal achchhā rahegā, to ham āge baṛheṁge.",ja:"もし試しがうまくいけば、次へ進みましょう。",note:"先のことは अगर のあとも未来形でよい。"},
   {hi:"अगर आपकी टीम व्यस्त है, तो हम ऑनलाइन शुरू कर सकते हैं।",rom:"agar āpkī ṭīm vyast hai, to ham onlāin shurū kar sakte haiṁ.",ja:"もしチームがお忙しければ、オンラインで始めることもできます。",note:"相手の事情に合わせた別の道を示す。"},
   {hi:"शायद मैं अगले महीने दिल्ली आऊँ।",rom:"shāyad maiṁ agle mahīne Dillī āūṁ.",ja:"来月、デリーにうかがうかもしれません。",note:"शायद＋接続法で「〜かもしれない」。まだ決まっていないとき。"},
   {hi:"क्या मैं आपकी टीम से मिलने आऊँ?",rom:"kyā maiṁ āpkī ṭīm se milne āūṁ?",ja:"チームの皆さんに会いにうかがいましょうか。",note:"क्या मैं … -ऊँ? で「〜しましょうか」。"},
   {hi:"आपके लिए कौन-सा विकल्प बेहतर है?",rom:"āpke lie kaun-sā vikalp behtar hai?",ja:"どちらの案がよろしいですか。",note:"相手に選んでもらう締めの質問。"},
   {hi:"अभी जवाब ज़रूरी नहीं है।",rom:"abhī javāb zarūrī nahīṁ hai.",ja:"今すぐお返事いただかなくて大丈夫です。",note:"相手に考える時間をあげると、信頼が生まれる。"},
   {hi:"आपकी सुविधा के हिसाब से तारीख़ तय करेंगे।",rom:"āpkī suvidhā ke hisāb se tārīkh tay kareṁge.",ja:"ご都合に合わせて日にちを決めましょう。",note:"के हिसाब से＝〜に合わせて。"},
   {hi:"क़ीमत की डिटेल्स के लिए हम अंग्रेज़ी में बात करें?",rom:"qīmat kī ḍiṭels ke lie ham angrezī meṁ bāt kareṁ?",ja:"料金の細かい点は、英語でお話ししましょうか。",note:"接続法 करें? で、英語への切り替えをていねいに提案。"}
  ],
  model:{title:"2つの案を出す商談の冒頭（シャルマさんへ）", time:"3分", note:"期間・日数・案の中身は練習用の例です。相手と話して決めた内容に入れかえましょう。", lines:[
   {hi:"नमस्ते शर्मा जी। आज फिर मिलने का मौक़ा देने के लिए धन्यवाद।",rom:"namaste Sharmā jī. āj phir milne kā mauqā dene ke lie dhanyavād.",ja:"シャルマさん、こんにちは。今日もまたお会いする機会をいただき、ありがとうございます。"},
   {hi:"पिछली बार मैंने ओमोतेनाशी के तीन छोटे क़दम बताए।",rom:"pichhlī bār maiṁne omotenāshī ke tīn chhoṭe qadam batāe.",ja:"前回は、おもてなしの3つの小さな一歩をお話ししました。"},
   {hi:"नाम से स्वागत, खाने से पहले छोटा सवाल, और कमरे में चप्पल।",rom:"nām se svāgat, khāne se pahle chhoṭā savāl, aur kamre meṁ chappal.",ja:"名前でお迎えする、食事の前に短く聞く、お部屋にスリッパ、の3つです。"},
   {hi:"आपकी टीम ने इन बातों में दिलचस्पी दिखाई। इसके लिए बहुत धन्यवाद।",rom:"āpkī ṭīm ne in bātoṁ meṁ dilchaspī dikhāī. iske lie bahut dhanyavād.",ja:"チームの皆さんが関心を持ってくださり、ありがとうございました。"},
   {hi:"अगर आपके पास दस मिनट हैं, तो आज मैं दो विकल्प दिखाना चाहता हूँ।",rom:"agar āpke pās das minaṭ haiṁ, to āj maiṁ do vikalp dikhānā chāhtā hūṁ.",ja:"もし10分いただければ、今日は2つの案をお見せしたいと思います。"},
   {hi:"पहला विकल्प: एक छोटा ट्रायल।",rom:"pahlā vikalp: ek chhoṭā ṭrāyal.",ja:"1つ目の案は、小さな試しです。"},
   {hi:"अगर आप चाहें, तो हम पहले एक रेस्टोरेंट में एक महीने का ट्रायल करें।",rom:"agar āp chāheṁ, to ham pahle ek resṭoranṭ meṁ ek mahīne kā ṭrāyal kareṁ.",ja:"よろしければ、まず1つのレストランで1か月、試してみましょう。"},
   {hi:"इसमें मैं आपकी टीम के साथ ऑनलाइन काम करूँगा।",rom:"ismeṁ maiṁ āpkī ṭīm ke sāth onlāin kām karūṁgā.",ja:"この案では、私がチームの皆さんとオンラインで一緒に取り組みます。"},
   {hi:"अगर ट्रायल अच्छा रहेगा, तो हम होटल में भी शुरू करेंगे।",rom:"agar ṭrāyal achchhā rahegā, to ham hoṭal meṁ bhī shurū kareṁge.",ja:"もし試しがうまくいけば、ホテルでも始めましょう。"},
   {hi:"दूसरा विकल्प: होटल और रेस्टोरेंट, दोनों में एक साथ शुरुआत।",rom:"dūsrā vikalp: hoṭal aur resṭoranṭ, donoṁ meṁ ek sāth shuruāt.",ja:"2つ目の案は、ホテルとレストランで同時に始めることです。"},
   {hi:"अगर आपकी टीम जल्दी शुरू करना चाहती है, तो यह विकल्प अच्छा है।",rom:"agar āpkī ṭīm jaldī shurū karnā chāhtī hai, to yah vikalp achchhā hai.",ja:"もしチームが早く始めたいなら、こちらの案がよいと思います。"},
   {hi:"इसके लिए शायद मैं अगले महीने दिल्ली आऊँ।",rom:"iske lie shāyad maiṁ agle mahīne Dillī āūṁ.",ja:"そのために、来月デリーにうかがうかもしれません。"},
   {hi:"अगर मैं दिल्ली आऊँगा, तो आपकी टीम के साथ दो दिन की ट्रेनिंग करूँगा।",rom:"agar maiṁ Dillī āūṁgā, to āpkī ṭīm ke sāth do din kī ṭrening karūṁgā.",ja:"もしデリーにうかがえば、チームの皆さんと2日間の研修をします。"},
   {hi:"अगर टीम व्यस्त है, तो हम ट्रेनिंग ऑनलाइन भी कर सकते हैं।",rom:"agar ṭīm vyast hai, to ham ṭrening onlāin bhī kar sakte haiṁ.",ja:"もしチームがお忙しければ、研修はオンラインでもできます。"},
   {hi:"दोनों विकल्पों में एक बात एक जैसी है।",rom:"donoṁ vikalpoṁ meṁ ek bāt ek jaisī hai.",ja:"どちらの案でも、変わらないことが1つあります。"},
   {hi:"हम छोटे से शुरू करेंगे और आपके मेहमानों की बात सुनेंगे।",rom:"ham chhoṭe se shurū kareṁge aur āpke mehmānoṁ kī bāt suneṁge.",ja:"小さく始めて、お客様の声を聞くことです。"},
   {hi:"मेरे लिए सबसे ज़रूरी है, सामने वाले मेहमान के लिए पूरी कोशिश।",rom:"mere lie sabse zarūrī hai, sāmne vāle mehmān ke lie pūrī koshish.",ja:"私にとっていちばん大切なのは、目の前のお客様に全力を尽くすことです。"},
   {hi:"तो शर्मा जी, आपके लिए कौन-सा विकल्प बेहतर है?",rom:"to Sharmā jī, āpke lie kaun-sā vikalp behtar hai?",ja:"シャルマさん、どちらの案がよろしいでしょうか。"},
   {hi:"अभी जवाब ज़रूरी नहीं है। आप चाहें तो टीम से बात करके बताइएगा।",rom:"abhī javāb zarūrī nahīṁ hai. āp chāheṁ to ṭīm se bāt karke batāiegā.",ja:"今すぐお返事いただかなくて大丈夫です。よろしければ、チームと話し合ってからお知らせください。"},
   {hi:"क़ीमत और कॉन्ट्रैक्ट की डिटेल्स के लिए हम अंग्रेज़ी में बात करें?",rom:"qīmat aur konṭraikṭ kī ḍiṭels ke lie ham angrezī meṁ bāt kareṁ?",ja:"料金と契約の細かい点は、英語でお話ししましょうか。"},
   {hi:"आपकी सुविधा के हिसाब से तारीख़ तय करेंगे। बहुत-बहुत धन्यवाद।",rom:"āpkī suvidhā ke hisāb se tārīkh tay kareṁge. bahut-bahut dhanyavād.",ja:"ご都合に合わせて日にちを決めましょう。ありがとうございました。"}
  ]},
  task:"インドの取引先の社長に、3分で商談の冒頭を話す。前回の話をふり返り、अगर … तो … で2つの案を出し、接続法（करें・आऊँ）を2回以上使い、「どちらがよろしいですか」と聞いて、細かい話は英語に切り替える提案で締める。",
  taskEn:"Give the three-minute opening of a business meeting with the head of an Indian partner company. Recap the last meeting, offer two options using if-then sentences, make soft suggestions such as \"shall we\" and \"I might come,\" ask which option they prefer, and suggest switching to English for the details.",
  qa:[
   {q:"अगर ट्रायल अच्छा नहीं रहेगा, तो क्या होगा?",qRom:"agar ṭrāyal achchhā nahīṁ rahegā, to kyā hogā?",a:"तो हम साथ में बात करेंगे और तरीक़ा बदलेंगे। फ़ैसला हमेशा आपका होगा।",aRom:"to ham sāth meṁ bāt kareṁge aur tarīqā badleṁge. faislā hameshā āpkā hogā.",ja:"質問：もし試しがうまくいかなかったら、どうなりますか。／答え：そのときは一緒に話し合って、やり方を変えます。決めるのはいつも御社です。"},
   {q:"आप दिल्ली कब आ सकते हैं?",qRom:"āp Dillī kab ā sakte haiṁ?",a:"शायद अगले महीने के बीच में आऊँ। आपकी सुविधा के हिसाब से तारीख़ तय करेंगे।",aRom:"shāyad agle mahīne ke bīch meṁ āūṁ. āpkī suvidhā ke hisāb se tārīkh tay kareṁge.",ja:"質問：デリーにはいつ来られますか。／答え：来月の半ばごろにうかがうかもしれません。ご都合に合わせて日にちを決めましょう。"},
   {q:"क्या ट्रेनिंग हिंदी में होगी?",qRom:"kyā ṭrening hindī meṁ hogī?",a:"मैं थोड़ी हिंदी बोलूँगा, लेकिन ज़्यादातर ट्रेनिंग अंग्रेज़ी में होगी। अगर ज़रूरत होगी, तो हम अनुवादक के साथ करेंगे।",aRom:"maiṁ thoṛī hindī bolūṁgā, lekin zyādātar ṭrening angrezī meṁ hogī. agar zarūrat hogī, to ham anuvādak ke sāth kareṁge.",ja:"質問：研修はヒンディー語でしますか。／答え：私も少しヒンディー語を話しますが、研修はほとんど英語です。必要なら、通訳の方と一緒に行います。"}
  ],
  check:[
   "案を1つだけでなく、अगर … तो … で2つ出せたか",
   "तो のあとに、自分が何をするかをはっきり言えたか",
   "接続法（करें?・आऊँ）で押しつけない言い方ができたか",
   "最後に「どちらがよろしいですか」と相手に選んでもらえたか",
   "料金や契約は英語で、と自然に切り替えを提案できたか"
  ],
  slide:"スライドを縦に2つに分け、左に「विकल्प 1：छोटा ट्रायल」、右に「विकल्प 2：एक साथ शुरुआत」。下に共通の1行「छोटे से शुरू करेंगे」を置きます。"}
]);

// プレゼン教科書 Week 34〜39
window.PRESENT=(window.PRESENT||[]).concat([
 {week:34, level:"A2", length:"3分", title:"くわしく説明する（जो…वह）",
  skill:"जो…वह・जहाँ…वहाँ・जब…तब を使って、院・システム・おもてなしの仕事を「どんな〜か」までくわしく説明できるようになる。",
  lesson:[
   "事業紹介が「院をやっています」「システムを作りました」だけだと、聞き手は中身を想像できません。この週は、名詞に説明をつける जो…वह を使って、「私が作ったシステムは…」「日本のお客様が来るホテルでは…」のように、一歩くわしく話す練習をします。",
   "जो…वह は日本語と同じく、説明を先に言ってから本体を受ける形です。जो सिस्टम मैंने बनाया, उसे…（私が作ったシステムを…）、जिस शहर में मेरा क्लिनिक है, उसका नाम…（院のある町の名前は…）。後ろに後置詞がつくと जिस・उस・जिन・उन に変わることに気をつけましょう。",
   "くわしく話すほど、聞き手は迷子になりやすくなります。最初に「仕事は3つあります」と数を言い、पहला・दूसरा・तीसरा で区切ると、長い説明でも頭に入ります。1つの文に जो を2回入れず、短い文を重ねるのがコツです。",
   "説明のあとには「たとえば」と例を1つ入れ（इसका एक उदाहरण देता हूँ）、途中で क्या यहाँ तक बात साफ़ है?（ここまでよろしいですか）と確かめます。最後は आसान शब्दों में कहूँ तो（簡単に言うと）で一言にまとめると、くわしさとわかりやすさの両方が残ります。"
  ],
  structure:[
   {hi:"परिचय",rom:"parichay",ja:"あいさつと「仕事は3つ」"},
   {hi:"क्लिनिक",rom:"klinik",ja:"院の説明（जिस शहर में…）"},
   {hi:"सिस्टम",rom:"sisṭam",ja:"システムの説明（जो सिस्टम…）"},
   {hi:"मेहमाननवाज़ी की सलाह",rom:"mehmānnavāzī kī salāh",ja:"おもてなしの手伝いと例"},
   {hi:"सारांश",rom:"sārānsh",ja:"ひと言のまとめと質問"}
  ],
  phrases:[
   {hi:"मैं आपको अपने काम के बारे में थोड़ा विस्तार से बताना चाहता हूँ।",rom:"maiṁ āpko apne kām ke bāre meṁ thoṛā vistār se batānā chāhtā hūṁ.",ja:"私の仕事について、少しくわしくお話ししたいと思います。",note:"विस्तार से ＝くわしく。説明に入る最初のひと言。"},
   {hi:"जिस शहर में मेरा क्लिनिक है, उसका नाम ओज़ू है।",rom:"jis shahar meṁ merā klinik hai, uskā nām Ozū hai.",ja:"私の院がある町の名前は、大洲です。",note:"में がつくので जो → जिस、受ける側も वह → उस（उसका）。"},
   {hi:"जो लोग हमारे क्लिनिक में आते हैं, वे ज़्यादातर आस-पास रहते हैं।",rom:"jo log hamāre klinik meṁ āte haiṁ, ve zyādātar ās-pās rahte haiṁ.",ja:"院に来る方の多くは、近くに住んでいます。",note:"複数の人なので受ける側は वे。"},
   {hi:"जो सिस्टम मैंने बनाया, उसे हमारे साथी क्लिनिक भी इस्तेमाल करते हैं।",rom:"jo sisṭam maiṁne banāyā, use hamāre sāthī klinik bhī istemāl karte haiṁ.",ja:"私が作ったシステムを、提携院も使っています。",note:"システムは「使われる側」なので उसे（उस＋को）で受ける。"},
   {hi:"यह वही सिस्टम है जो हमारे साथी क्लिनिक भी इस्तेमाल करते हैं।",rom:"yah vahī sisṭam hai jo hamāre sāthī klinik bhī istemāl karte haiṁ.",ja:"これが、提携院も使っている、まさにそのシステムです。",note:"वही ＝まさにその。名詞を先に言って जो で説明を足す話し言葉の順番。"},
   {hi:"जब से मैंने क्लिनिक खोला, तब से मैं हर दिन नंबर देखता हूँ।",rom:"jab se maiṁne klinik kholā, tab se maiṁ har din nambar dekhtā hūṁ.",ja:"院を開いてから、毎日数字を見ています。",note:"जब से … तब से ＝「〜して以来ずっと」。"},
   {hi:"जिन होटलों में जापानी मेहमान आते हैं, उनके स्टाफ़ के साथ मैं काम करता हूँ।",rom:"jin hoṭaloṁ meṁ jāpānī mehmān āte haiṁ, unke sṭāf ke sāth maiṁ kām kartā hūṁ.",ja:"日本のお客様が来るホテルで、そのスタッフの方と一緒に仕事をしています。",note:"複数の होटलों なので जिन…उन。"},
   {hi:"इसका एक उदाहरण देता हूँ।",rom:"iskā ek udāharaṇ detā hūṁ.",ja:"一つ例を挙げます。",note:"説明のあとに例を1つ。聞き手の顔が明るくなる合図。"},
   {hi:"क्या यहाँ तक बात साफ़ है?",rom:"kyā yahāṁ tak bāt sāf hai?",ja:"ここまでのお話は、わかりやすいでしょうか。",note:"長い説明の途中で一度だけ確かめる。"},
   {hi:"आसान शब्दों में कहूँ तो, मेरे तीनों काम एक ही बात पर टिके हैं।",rom:"āsān shabdoṁ meṁ kahūṁ to, mere tīnoṁ kām ek hī bāt par ṭike haiṁ.",ja:"簡単に言うと、私の3つの仕事は、ひとつの考えの上に立っています。",note:"決まり文句として覚える（कहूँ तो ＝言うなら）。まとめの合図。"}
  ],
  model:{title:"私の3つの仕事をくわしく（取引先のホテルの方へ）", time:"3分", note:"院の開業年・スタッフ数・3つの仕事は事実にそった内容です。おもてなしの例は、自分の言葉で入れかえてもかまいません。", lines:[
   {hi:"नमस्ते प्रिया जी, नमस्ते शर्मा जी। आज समय देने के लिए धन्यवाद।",rom:"namaste Priyā jī, namaste Sharmā jī. āj samay dene ke lie dhanyavād.",ja:"プリヤさん、シャルマさん、こんにちは。今日はお時間をいただき、ありがとうございます。"},
   {hi:"पिछली बार मैंने अपना छोटा-सा परिचय दिया था। आज मैं अपने काम के बारे में थोड़ा विस्तार से बताना चाहता हूँ।",rom:"pichhlī bār maiṁne apnā chhoṭā-sā parichay diyā thā. āj maiṁ apne kām ke bāre meṁ thoṛā vistār se batānā chāhtā hūṁ.",ja:"前回は短く自己紹介をしました。今日は、私の仕事について少しくわしくお話ししたいと思います。"},
   {hi:"मेरे काम के तीन हिस्से हैं। क्लिनिक, बुकिंग सिस्टम, और मेहमाननवाज़ी की सलाह।",rom:"mere kām ke tīn hisse haiṁ. klinik, buking sisṭam, aur mehmānnavāzī kī salāh.",ja:"私の仕事は3つに分かれています。院、予約システム、そしておもてなしのコンサルです。"},
   {hi:"पहला, क्लिनिक। जिस शहर में मेरा क्लिनिक है, उसका नाम ओज़ू है।",rom:"pahlā, klinik. jis shahar meṁ merā klinik hai, uskā nām Ozū hai.",ja:"1つ目は院です。私の院がある町は、大洲といいます。"},
   {hi:"ओज़ू एहिमे में है। यह एक छोटा शहर है, जहाँ नदी और पहाड़ बहुत सुंदर हैं।",rom:"Ozū Ehime meṁ hai. yah ek chhoṭā shahar hai, jahāṁ nadī aur pahāṛ bahut sundar haiṁ.",ja:"大洲は愛媛にあります。川と山がとてもきれいな、小さな町です。"},
   {hi:"मैंने यह क्लिनिक 2018 में खोला था। अब मेरे साथ चार स्टाफ़ काम करते हैं।",rom:"maiṁne yah klinik 2018 meṁ kholā thā. ab mere sāth chār sṭāf kām karte haiṁ.",ja:"この院は2018年に開きました。今は4人のスタッフと一緒に働いています。"},
   {hi:"जो लोग हमारे क्लिनिक में आते हैं, वे ज़्यादातर आस-पास के इलाक़े में रहते हैं।",rom:"jo log hamāre klinik meṁ āte haiṁ, ve zyādātar ās-pās ke ilāqe meṁ rahte haiṁ.",ja:"院に来る方の多くは、近くの地域に住んでいる方です。"},
   {hi:"दूसरा, बुकिंग सिस्टम। जब से मैंने क्लिनिक खोला, तब से मैं हर दिन तीन चीज़ें देखता हूँ।",rom:"dūsrā, buking sisṭam. jab se maiṁne klinik kholā, tab se maiṁ har din tīn chīzeṁ dekhtā hūṁ.",ja:"2つ目は予約システムです。院を開いてから、私は毎日3つのことを見ています。"},
   {hi:"बिक्री, आने वाले लोगों की संख्या, और दोबारा आने वाले लोगों की दर।",rom:"bikrī, āne vāle logoṁ kī sankhyā, aur dobārā āne vāle logoṁ kī dar.",ja:"売上、来院数、そして再来院率です。"},
   {hi:"इसके लिए मैंने बुकिंग और ग्राहकों का रिकॉर्ड रखने का एक सिस्टम बनाया।",rom:"iske lie maiṁne buking aur grāhakoṁ kā rikorḍ rakhne kā ek sisṭam banāyā.",ja:"そのために、予約とお客様の記録を残すシステムを作りました。"},
   {hi:"यह वही सिस्टम है जो आज हमारे साथी क्लिनिक भी इस्तेमाल करते हैं।",rom:"yah vahī sisṭam hai jo āj hamāre sāthī klinik bhī istemāl karte haiṁ.",ja:"これが、今は提携院でも使われている、そのシステムです。"},
   {hi:"जिन क्लिनिकों के साथ हम काम करते हैं, उनकी मैं मैनेजमेंट में भी मदद करता हूँ।",rom:"jin klinikoṁ ke sāth ham kām karte haiṁ, unkī maiṁ mainejmenṭ meṁ bhī madad kartā hūṁ.",ja:"一緒に仕事をしている院には、経営のお手伝いもしています。"},
   {hi:"तीसरा, मेहमाननवाज़ी की सलाह। यह काम भारत की कंपनियों के लिए है।",rom:"tīsrā, mehmānnavāzī kī salāh. yah kām Bhārat kī kampaniyoṁ ke lie hai.",ja:"3つ目は、おもてなしのコンサルです。これはインドの会社のための仕事です。"},
   {hi:"जिन होटलों और रेस्टोरेंट में जापानी मेहमान आते हैं, उनके स्टाफ़ के साथ मैं मिलकर काम करता हूँ।",rom:"jin hoṭaloṁ aur resṭoranṭ meṁ jāpānī mehmān āte haiṁ, unke sṭāf ke sāth maiṁ milkar kām kartā hūṁ.",ja:"日本のお客様が来るホテルやレストランで、スタッフの皆さんと一緒に取り組みます。"},
   {hi:"इसका एक उदाहरण देता हूँ। जब मेहमान आते हैं, तब सिर्फ़ नमस्ते कहना काफ़ी नहीं होता।",rom:"iskā ek udāharaṇ detā hūṁ. jab mehmān āte haiṁ, tab sirf namaste kahnā kāfī nahīṁ hotā.",ja:"一つ例を挙げます。お客様が来たとき、あいさつだけでは十分ではありません。"},
   {hi:"जो मेहमान थका हुआ है, उसे पहले पानी और आराम चाहिए।",rom:"jo mehmān thakā huā hai, use pahle pānī aur ārām chāhie.",ja:"疲れているお客様には、まず水と休む場所が必要です。"},
   {hi:"मतलब, मेहमान को जिस चीज़ की ज़रूरत है, वही पहले देना। यही जापानी मेहमाननवाज़ी का दिल है।",rom:"matlab, mehmān ko jis chīz kī zarūrat hai, vahī pahle denā. yahī jāpānī mehmānnavāzī kā dil hai.",ja:"つまり、お客様がいちばん必要としているものを、先に差し出すこと。これが日本のおもてなしの心です。"},
   {hi:"क्या यहाँ तक बात साफ़ है?",rom:"kyā yahāṁ tak bāt sāf hai?",ja:"ここまでのお話は、わかりやすいでしょうか。"},
   {hi:"आसान शब्दों में कहूँ तो, मेरे तीनों काम एक ही बात पर टिके हैं।",rom:"āsān shabdoṁ meṁ kahūṁ to, mere tīnoṁ kām ek hī bāt par ṭike haiṁ.",ja:"簡単に言うと、私の3つの仕事は、ひとつの考えの上に立っています。"},
   {hi:"जो इंसान मेरे सामने है, उसके लिए पूरी कोशिश करना।",rom:"jo insān mere sāmne hai, uske lie pūrī koshish karnā.",ja:"目の前の人に、全力を尽くすことです。"},
   {hi:"सुनने के लिए धन्यवाद। अब आपके सवाल सुनना चाहूँगा।",rom:"sunne ke lie dhanyavād. ab āpke savāl sunnā chāhūṁgā.",ja:"聞いてくださってありがとうございます。では、ご質問をお聞きしたいと思います。"}
  ]},
  task:"取引先（インドのホテル・クリニックの方）に向けて、自分の仕事を3つに分け、それぞれを जो…वह・जिस…उस・जब…तब で一歩くわしく説明する3分のプレゼンを話す。例を1つ入れ、最後はひと言でまとめる。",
  taskEn:"Give a 3-minute presentation in Hindi to Indian business partners (a hotel or clinic). Explain your three lines of work in more detail using relative clauses (जो…वह, जिस…उस, जब…तब), include one concrete example, and finish with a one-sentence summary.",
  qa:[
   {q:"आपके क्लिनिक में कौन लोग ज़्यादा आते हैं?",qRom:"āpke klinik meṁ kaun log zyādā āte haiṁ?",a:"जो लोग आस-पास रहते हैं, वे सबसे ज़्यादा आते हैं।",aRom:"jo log ās-pās rahte haiṁ, ve sabse zyādā āte haiṁ.",ja:"院にはどんな方がよく来ますか。／近くに住んでいる方が、いちばんよく来ます。"},
   {q:"आप होटलों के साथ क्या काम करते हैं?",qRom:"āp hoṭaloṁ ke sāth kyā kām karte haiṁ?",a:"जिन होटलों में जापानी मेहमान आते हैं, उनके स्टाफ़ को मैं जापानी मेहमाननवाज़ी के बारे में बताता हूँ।",aRom:"jin hoṭaloṁ meṁ jāpānī mehmān āte haiṁ, unke sṭāf ko maiṁ jāpānī mehmānnavāzī ke bāre meṁ batātā hūṁ.",ja:"ホテルとはどんな仕事をしているのですか。／日本のお客様が来るホテルで、スタッフの方に日本のおもてなしをお伝えしています。"},
   {q:"आप भारत कितनी बार आते हैं?",qRom:"āp Bhārat kitnī bār āte haiṁ?",a:"मैं नियमित रूप से भारत आता हूँ। जब भी आता हूँ, तब अपने साथियों से ज़रूर मिलता हूँ।",aRom:"maiṁ niyamit rūp se Bhārat ātā hūṁ. jab bhī ātā hūṁ, tab apne sāthiyoṁ se zarūr miltā hūṁ.",ja:"インドにはどのくらい来ますか。／定期的に来ています。来るたびに、仲間に必ず会います。"}
  ],
  check:[
   "jo で始めた文を、vah・ve・use・uskā などで正しく受けられたか",
   "後置詞がつくとき jis・jin・us・un に変えられたか",
   "「仕事は3つ」と最初に数を言い、pahlā・dūsrā・tīsrā で区切れたか",
   "例を1つ入れ、最後をひと言でまとめられたか",
   "1つの文に jo を2回入れず、短い文で話せたか"
  ],
  slide:"スライドは3列にして、院・システム・おもてなしを1語ずつ大きく書き、下に写真を1枚ずつ。くわしい説明は口で話し、字は増やしません。"},

 {week:35, level:"A2", length:"3分", title:"仲間を励ますスピーチ（-ते रहिए）",
  skill:"仲間の前で、感謝 → 仲間のがんばりをほめる → 自分の経験 → 励まし（-ते रहिए）の順で、心のこもった3分のスピーチができるようになる。",
  lesson:[
   "仲間を励ますスピーチは、まず感謝から始めます。忙しい中で集まってくれたこと（जुड़ने के लिए धन्यवाद）、毎月続けていることそのものを、言葉にしてほめましょう。人は「見てもらえている」と感じると、また頑張れます。",
   "次に、仲間の名前を出して、具体的なできごとをほめます。「みんなすごい」より「ネハさんが先月、初めてみんなの前で話した」のほうが、ずっと心に届きます。आपने बहुत अच्छा काम किया!（よくがんばりましたね）を、相手の目を見て言いましょう。",
   "励ましの中心は、自分の経験です。開業したばかりのころのこと、ヒンディー語をゼロから学んでいることなど、うまくいかなかった話を正直にすると、聞き手は「自分だけじゃない」と思えます。上から教える話し方ではなく、同じ道を歩く仲間として話します。",
   "締めは -ते रहिए の3連打が効きます。सीखते रहिए, मुस्कुराते रहिए, और मिलते रहिए（学び続けて、笑顔で、また会いましょう）。ここは励ましと感謝の場なので、商品や仕事の誘いの話は入れません。"
  ],
  structure:[
   {hi:"अभिवादन और धन्यवाद",rom:"abhivādan aur dhanyavād",ja:"あいさつと感謝"},
   {hi:"तारीफ़",rom:"tārīf",ja:"仲間のがんばりをほめる"},
   {hi:"मेरा अनुभव",rom:"merā anubhav",ja:"自分の経験"},
   {hi:"हौसला",rom:"hauslā",ja:"励まし（-ते रहिए）"},
   {hi:"समापन",rom:"samāpan",ja:"締めのひと言"}
  ],
  phrases:[
   {hi:"आज जुड़ने के लिए आप सबका दिल से धन्यवाद।",rom:"āj juṛne ke lie āp sabkā dil se dhanyavād.",ja:"今日参加してくださった皆さんに、心から感謝します。",note:"दिल से ＝心から。オンラインの集まりの最初に。"},
   {hi:"पिछले महीने आप सबने बहुत मेहनत की।",rom:"pichhle mahīne āp sabne bahut mehnat kī.",ja:"先月、皆さんは本当によくがんばりました。",note:"मेहनत（女）なので की。ने 構文。"},
   {hi:"नेहा जी, आपने बहुत अच्छा काम किया!",rom:"Nehā jī, āpne bahut achchhā kām kiyā!",ja:"ネハさん、よくがんばりましたね！",note:"名前を呼んでからほめると、本人にまっすぐ届く。"},
   {hi:"आप ज़रूर कर सकते हैं!",rom:"āp zarūr kar sakte haiṁ!",ja:"あなたならきっとできます！",note:"女性一人に言うときは कर सकती हैं。"},
   {hi:"हिम्मत रखिए, हार मत मानिए।",rom:"himmat rakhie, hār mat mānie.",ja:"元気を出して、あきらめないでください。",note:"日本語の「がんばって」に近い決まり文句。"},
   {hi:"रोज़ थोड़ा-थोड़ा सीखते रहिए।",rom:"roz thoṛā-thoṛā sīkhte rahie.",ja:"毎日少しずつ、学び続けてください。",note:"語幹＋ते रहिए ＝〜し続けてください。"},
   {hi:"हर किसी का रास्ता अलग होता है।",rom:"har kisī kā rāstā alag hotā hai.",ja:"一人ひとり、歩く道は違います。",note:"होता है ＝一般的にそうだ、という言い方。"},
   {hi:"छोटा क़दम भी एक क़दम है।",rom:"chhoṭā qadam bhī ek qadam hai.",ja:"小さな一歩も、一歩です。",note:"短くて覚えやすい。スピーチの山場に。"},
   {hi:"चिंता मत कीजिए, हम सब आपके साथ हैं।",rom:"chintā mat kījie, ham sab āpke sāth haiṁ.",ja:"心配しないでください、私たちはみんなあなたと一緒です。",note:"不安そうな人へのひと言。"},
   {hi:"मुस्कुराते रहिए और मिलते रहिए!",rom:"muskurāte rahie aur milte rahie!",ja:"笑顔でいてくださいね。また会いましょう！",note:"-ते रहिए を2つ重ねた、明るい締めの言葉。"}
  ],
  model:{title:"毎月のオンラインの集まりで仲間を励ます", time:"3分", note:"ネハさん・アルジュンさんの名前とできごとは練習用の例です。実際の仲間の名前とがんばりに入れかえましょう。", lines:[
   {hi:"नमस्ते दोस्तों! आप सब कैसे हैं?",rom:"namaste doston! āp sab kaise haiṁ?",ja:"皆さん、こんにちは！お元気ですか。"},
   {hi:"आज भी इतने लोग जुड़े हैं, यह देखकर मुझे बहुत ख़ुशी हो रही है।",rom:"āj bhī itne log juṛe haiṁ, yah dekhkar mujhe bahut khushī ho rahī hai.",ja:"今日もこんなにたくさんの方が参加してくれて、とてもうれしいです。"},
   {hi:"सबसे पहले, आज जुड़ने के लिए आप सबका दिल से धन्यवाद।",rom:"sabse pahle, āj juṛne ke lie āp sabkā dil se dhanyavād.",ja:"まず、今日参加してくださった皆さんに、心から感謝します。"},
   {hi:"मैं जानता हूँ कि आप सब बहुत व्यस्त हैं। काम, परिवार, और पढ़ाई, सब एक साथ।",rom:"maiṁ jāntā hūṁ ki āp sab bahut vyast haiṁ. kām, parivār, aur paṛhāī, sab ek sāth.",ja:"皆さんがとても忙しいことは知っています。仕事、家族、勉強、全部を一度にしているのですから。"},
   {hi:"फिर भी आप हर महीने समय निकालते हैं। यह अपने आप में कमाल है।",rom:"phir bhī āp har mahīne samay nikālte haiṁ. yah apne āp meṁ kamāl hai.",ja:"それでも毎月、時間を作ってくれています。それだけで、すごいことです。"},
   {hi:"पिछले महीने नेहा जी ने पहली बार सबके सामने बात की।",rom:"pichhle mahīne Nehā jī ne pahlī bār sabke sāmne bāt kī.",ja:"先月、ネハさんが初めて、みんなの前で話をしました。"},
   {hi:"वे थोड़ी घबराई हुई थीं, लेकिन उन्होंने आख़िर तक बात पूरी की। नेहा जी, बहुत बढ़िया!",rom:"ve thoṛī ghabrāī huī thīṁ, lekin unhoṁne ākhir tak bāt pūrī kī. Nehā jī, bahut baṛhiyā!",ja:"少し緊張していましたが、最後まで話しきりました。ネハさん、すばらしかったです！"},
   {hi:"और अर्जुन जी हर हफ़्ते नए साथियों की मदद करते रहे। अर्जुन जी, आपकी मेहनत के लिए धन्यवाद।",rom:"aur Arjun jī har hafte nae sāthiyoṁ kī madad karte rahe. Arjun jī, āpkī mehnat ke lie dhanyavād.",ja:"それからアルジュンさんは、毎週、新しい仲間を手伝い続けてくれました。アルジュンさん、がんばりをありがとう。"},
   {hi:"अब मैं अपना एक छोटा-सा अनुभव बताना चाहता हूँ।",rom:"ab maiṁ apnā ek chhoṭā-sā anubhav batānā chāhtā hūṁ.",ja:"ここで、私の小さな経験をお話しさせてください。"},
   {hi:"2018 में मैंने ओज़ू में अपना क्लिनिक खोला। शुरू में मेरे लिए सब कुछ नया था।",rom:"2018 meṁ maiṁne Ozū meṁ apnā klinik kholā. shurū meṁ mere lie sab kuchh nayā thā.",ja:"2018年、私は大洲で院を開きました。はじめは、すべてが初めてのことでした。"},
   {hi:"कई बार मुझे लगा कि यह बहुत मुश्किल है।",rom:"kaī bār mujhe lagā ki yah bahut mushkil hai.",ja:"何度も「これはとても難しい」と感じました。"},
   {hi:"तब मैंने एक बात तय की। जो इंसान मेरे सामने है, उसके लिए पूरी कोशिश करूँगा।",rom:"tab maiṁne ek bāt tay kī. jo insān mere sāmne hai, uske lie pūrī koshish karūṁgā.",ja:"そのとき、ひとつ決めました。目の前の人に、全力を尽くそう、と。"},
   {hi:"हर दिन मैं बस यही करता रहा।",rom:"har din maiṁ bas yahī kartā rahā.",ja:"毎日、ただそれだけを続けてきました。"},
   {hi:"और अब मैं हिंदी भी सीख रहा हूँ, बिल्कुल शुरू से। मेरी हिंदी अभी बहुत कच्ची है।",rom:"aur ab maiṁ hindī bhī sīkh rahā hūṁ, bilkul shurū se. merī hindī abhī bahut kachchī hai.",ja:"そして今、私はヒンディー語もゼロから学んでいます。私のヒンディー語は、まだまだです。"},
   {hi:"लेकिन मैं रोज़ थोड़ा-थोड़ा सीखता हूँ। आज आपके सामने हिंदी में बोल रहा हूँ, यही मेरे लिए बड़ी बात है।",rom:"lekin maiṁ roz thoṛā-thoṛā sīkhtā hūṁ. āj āpke sāmne hindī meṁ bol rahā hūṁ, yahī mere lie baṛī bāt hai.",ja:"でも、毎日少しずつ学んでいます。今日こうして皆さんの前でヒンディー語で話せていること、それが私には大きなことです。"},
   {hi:"दोस्तों, हर किसी का रास्ता अलग होता है। कोई तेज़ चलता है, कोई धीरे।",rom:"doston, har kisī kā rāstā alag hotā hai. koī tez chaltā hai, koī dhīre.",ja:"皆さん、一人ひとり歩く道は違います。速く歩く人もいれば、ゆっくりの人もいます。"},
   {hi:"धीरे चलना ग़लत नहीं है। छोटा क़दम भी एक क़दम है।",rom:"dhīre chalnā ghalat nahīṁ hai. chhoṭā qadam bhī ek qadam hai.",ja:"ゆっくり歩くのは、まちがいではありません。小さな一歩も、一歩です。"},
   {hi:"अगर कभी थकान लगे, तो हिम्मत रखिए। हार मत मानिए।",rom:"agar kabhī thakān lage, to himmat rakhie. hār mat mānie.",ja:"もし疲れたと感じたら、元気を出してください。あきらめないでください。"},
   {hi:"अपने लक्ष्य को याद रखिए, और रोज़ थोड़ा-थोड़ा आगे बढ़ते रहिए।",rom:"apne lakshya ko yād rakhie, aur roz thoṛā-thoṛā āge baṛhte rahie.",ja:"自分の目標を忘れずに、毎日少しずつ前に進み続けてください。"},
   {hi:"चिंता मत कीजिए, हम सब एक-दूसरे के साथ हैं।",rom:"chintā mat kījie, ham sab ek-dūsre ke sāth haiṁ.",ja:"心配しないでください。私たちはみんな、お互いに一緒です。"},
   {hi:"आप ज़रूर कर सकते हैं। मुझे आप सब पर पूरा भरोसा है।",rom:"āp zarūr kar sakte haiṁ. mujhe āp sab par pūrā bharosā hai.",ja:"皆さんなら、きっとできます。私は皆さんを心から信じています。"},
   {hi:"तो सीखते रहिए, मुस्कुराते रहिए, और मिलते रहिए। बहुत-बहुत शुक्रिया!",rom:"to sīkhte rahie, muskurāte rahie, aur milte rahie. bahut-bahut shukriyā!",ja:"では、学び続けて、笑顔でいて、また会いましょう。本当にありがとうございました！"}
  ]},
  task:"インドの仲間のオンラインの集まりで、3分の励ましのスピーチをする。感謝 → 仲間2人の名前と具体的ながんばり → 自分の経験（開業のころ・ヒンディー語の勉強）→ -ते रहिए を3つ使った励まし、の順で話す。勧誘や商品の話は入れない。",
  taskEn:"Give a 3-minute encouraging speech in Hindi at an online meeting of your Indian friends and colleagues. Thank them, praise two people by name for something specific, share your own experience (starting your clinic, learning Hindi from zero), and close with three -ते रहिए encouragements. No sales or recruiting talk.",
  qa:[
   {q:"आप इतनी हिंदी कैसे सीख रहे हैं?",qRom:"āp itnī hindī kaise sīkh rahe haiṁ?",a:"मैं रोज़ थोड़ा-थोड़ा अभ्यास करता हूँ। आप सबसे बात करना भी मेरा अभ्यास है।",aRom:"maiṁ roz thoṛā-thoṛā abhyās kartā hūṁ. āp sabse bāt karnā bhī merā abhyās hai.",ja:"どうやってそんなにヒンディー語を学んでいるのですか。／毎日少しずつ練習しています。皆さんと話すことも、私の練習です。"},
   {q:"जब आपको मुश्किल लगता है, तब आप क्या करते हैं?",qRom:"jab āpko mushkil lagtā hai, tab āp kyā karte haiṁ?",a:"मैं अपना लक्ष्य याद करता हूँ, और जो इंसान मेरे सामने है, उसके लिए पूरी कोशिश करता हूँ।",aRom:"maiṁ apnā lakshya yād kartā hūṁ, aur jo insān mere sāmne hai, uske lie pūrī koshish kartā hūṁ.",ja:"難しいと感じたとき、どうしていますか。／自分の目標を思い出して、目の前の人に全力を尽くします。"},
   {q:"आपकी बातों से मुझे बहुत हौसला मिला।",qRom:"āpkī bātoṁ se mujhe bahut hauslā milā.",a:"तारीफ़ के लिए धन्यवाद। आपकी मेहनत से मुझे भी हौसला मिलता है।",aRom:"tārīf ke lie dhanyavād. āpkī mehnat se mujhe bhī hauslā miltā hai.",ja:"あなたのお話で、とても元気が出ました。／ありがとうございます。あなたのがんばりから、私も元気をもらっています。"}
  ],
  check:[
   "最初に、参加してくれたことへの感謝を言えたか",
   "仲間の名前を出して、具体的なできごとをほめられたか",
   "自分の経験を、上から教える調子ではなく正直に話せたか",
   "sīkhte rahie などの -te rahie を3つ使えたか",
   "勧誘・商品・お金の話が入っていないか"
  ],
  slide:"スライドは使わず、顔を見て話すのがおすすめ。使うなら最後に「सीखते रहिए・मुस्कुराते रहिए・मिलते रहिए」の3行だけを大きく映します。"},

 {week:36, level:"A2", length:"3分30秒", title:"集まりの司会と開会のあいさつ",
  skill:"仲間のオンライン勉強会で、開会のあいさつ → テーマと進め方 → 話す人の紹介 → 質問の受けつけ → まとめと締め、まで司会を通してできるようになる。",
  lesson:[
   "司会の仕事は、自分が目立つことではなく、場を安心させることです。最初の30秒で「声が届いているか」を確かめ、आप सबका स्वागत है（ようこそ）と歓迎し、時間を作ってくれたお礼を言います。これだけで、場の空気が落ち着きます。",
   "次に、テーマと進め方を短く伝えます。「今日は1時間、最初の20分は〇〇さんの話、そのあと話し合い、最後に質問」のように、時間の地図を先に渡すと、聞き手は安心して参加できます。マイクのミュートやチャットの使い方のお願いも、ここで一度だけていねいに言います。",
   "話す人を紹介するときは、名前・その人のがんばり・今日の話への期待を1〜2文で。जो इंसान…, उससे हमें…सीखना चाहिए のように、第34週の जो…वह と今週の -ना चाहिए を組み合わせると、紹介に気持ちがこもります。",
   "質問の時間は、क्या किसी का कोई सवाल है? と聞いて少し待ちます。質問が出たら बहुत अच्छा सवाल है, धन्यवाद とまず感謝。最後は今日の要点を3つにまとめ、आज के लिए बस इतना ही → お礼 → 次回の予告、の順で締めます。"
  ],
  structure:[
   {hi:"स्वागत",rom:"svāgat",ja:"音の確認と開会のあいさつ"},
   {hi:"आज का विषय",rom:"āj kā vishay",ja:"テーマと進め方・お願い"},
   {hi:"वक्ता का परिचय",rom:"vaktā kā parichay",ja:"話す人の紹介"},
   {hi:"सवाल-जवाब",rom:"savāl-javāb",ja:"質問の受けつけ"},
   {hi:"सारांश और समापन",rom:"sārānsh aur samāpan",ja:"まとめと締め・次回の予告"}
  ],
  phrases:[
   {hi:"आज के सत्र में आप सबका स्वागत है।",rom:"āj ke satr meṁ āp sabkā svāgat hai.",ja:"今日の会へようこそ。",note:"開会のいちばん基本のひと言。"},
   {hi:"समय निकालने के लिए आप सबका बहुत-बहुत धन्यवाद।",rom:"samay nikālne ke lie āp sabkā bahut-bahut dhanyavād.",ja:"時間を作ってくださって、本当にありがとうございます。",note:"忙しい中で来てくれた人への決まり文句。"},
   {hi:"आज मैं, आकिहिरो, इस सत्र का संचालन करूँगा।",rom:"āj maiṁ, Ākihiro, is satr kā sanchālan karūṁgā.",ja:"今日は私、アキヒロが司会を務めます。",note:"संचालन ＝司会・進行。"},
   {hi:"आज का विषय है, समय का सही इस्तेमाल।",rom:"āj kā vishay hai, samay kā sahī istemāl.",ja:"今日のテーマは、時間の上手な使い方です。",note:"विषय है, … と区切って、テーマをはっきり言う。"},
   {hi:"कृपया अपना माइक म्यूट रखिए।",rom:"kripayā apnā māik myūṭ rakhie.",ja:"マイクはミュートにしておいてください。",note:"オンラインの会で一度だけ、ていねいに。"},
   {hi:"अब मैं आज की वक्ता का परिचय देता हूँ।",rom:"ab maiṁ āj kī vaktā kā parichay detā hūṁ.",ja:"では、今日話してくださる方をご紹介します。",note:"話す人が女性なら की वक्ता、男性なら का वक्ता。"},
   {hi:"क्या किसी का कोई सवाल है?",rom:"kyā kisī kā koī savāl hai?",ja:"どなたか質問はありますか。",note:"聞いたあと、3秒ほど待つ。"},
   {hi:"बहुत अच्छा सवाल है, धन्यवाद।",rom:"bahut achchhā savāl hai, dhanyavād.",ja:"とてもいい質問です、ありがとうございます。",note:"質問してくれた人に、まず感謝。"},
   {hi:"हमें एक-दूसरे से सीखना चाहिए।",rom:"hameṁ ek-dūsre se sīkhnā chāhie.",ja:"私たちはお互いから学ぶべきですね。",note:"हमें ＋ -ना ＋ चाहिए ＝私たちは〜すべき。"},
   {hi:"आज के लिए बस इतना ही। अगली बार फिर मिलेंगे।",rom:"āj ke lie bas itnā hī. aglī bār phir mileṁge.",ja:"今日はここまでです。また次回お会いしましょう。",note:"締めの決まり文句。"}
  ],
  model:{title:"仲間のオンライン勉強会の司会（テーマ：時間の上手な使い方）", time:"3分30秒", note:"曜日・時間・名前・まとめの中身は練習用の例です。ネハさんの話（約20分）は、17行目の前に入ります。", lines:[
   {hi:"नमस्ते दोस्तों! क्या मेरी आवाज़ आ रही है?",rom:"namaste doston! kyā merī āvāz ā rahī hai?",ja:"皆さん、こんにちは！私の声は聞こえていますか。"},
   {hi:"बहुत अच्छा। तो चलिए, शुरू करते हैं।",rom:"bahut achchhā. to chalie, shurū karte haiṁ.",ja:"よかったです。では、始めましょう。"},
   {hi:"आज के सत्र में आप सबका स्वागत है।",rom:"āj ke satr meṁ āp sabkā svāgat hai.",ja:"今日の会へようこそ。"},
   {hi:"रविवार की सुबह है, फिर भी आप सबने समय निकाला। इसके लिए आप सबका बहुत-बहुत धन्यवाद।",rom:"ravivār kī subah hai, phir bhī āp sabne samay nikālā. iske lie āp sabkā bahut-bahut dhanyavād.",ja:"日曜の朝なのに、皆さん時間を作ってくださいました。本当にありがとうございます。"},
   {hi:"आज मैं, आकिहिरो, इस सत्र का संचालन करूँगा। मैं जापान से जुड़ा हूँ।",rom:"āj maiṁ, Ākihiro, is satr kā sanchālan karūṁgā. maiṁ Jāpān se juṛā hūṁ.",ja:"今日は私、アキヒロが司会を務めます。日本からつないでいます。"},
   {hi:"मेरी हिंदी अभी सीखने वाली हिंदी है, इसलिए कोई ग़लती हो तो माफ़ कीजिए।",rom:"merī hindī abhī sīkhne vālī hindī hai, islie koī ghalatī ho to māf kījie.",ja:"私のヒンディー語はまだ勉強中なので、まちがいがあったらごめんなさい。"},
   {hi:"आज का विषय है, समय का सही इस्तेमाल।",rom:"āj kā vishay hai, samay kā sahī istemāl.",ja:"今日のテーマは、時間の上手な使い方です。"},
   {hi:"हम सबके पास दिन में चौबीस घंटे होते हैं। फिर भी किसी के पास समय ज़्यादा लगता है, किसी के पास कम।",rom:"ham sabke pās din meṁ chaubīs ghanṭe hote haiṁ. phir bhī kisī ke pās samay zyādā lagtā hai, kisī ke pās kam.",ja:"だれにでも1日は24時間あります。それでも、時間がたくさんあるように見える人もいれば、少ない人もいます。"},
   {hi:"आज का कार्यक्रम एक घंटे का है। पहले बीस मिनट नेहा जी अपना अनुभव साझा करेंगी।",rom:"āj kā kāryakram ek ghanṭe kā hai. pahle bīs minaṭ Nehā jī apnā anubhav sājhā kareṁgī.",ja:"今日の会は1時間です。最初の20分は、ネハさんが自分の経験を話してくれます。"},
   {hi:"उसके बाद छोटे समूहों में चर्चा होगी, और आख़िर में सवाल-जवाब का समय होगा।",rom:"uske bād chhoṭe samūhoṁ meṁ charchā hogī, aur ākhir meṁ savāl-javāb kā samay hogā.",ja:"そのあと小さなグループで話し合い、最後に質問の時間があります。"},
   {hi:"एक छोटी-सी बात। जब कोई बोल रहा हो, तब कृपया अपना माइक म्यूट रखिए।",rom:"ek chhoṭī-sī bāt. jab koī bol rahā ho, tab kripayā apnā māik myūṭ rakhie.",ja:"ひとつだけお願いです。だれかが話しているときは、マイクをミュートにしておいてください。"},
   {hi:"अगर कोई सवाल हो, तो चैट में लिख दीजिए।",rom:"agar koī savāl ho, to chaiṭ meṁ likh dījie.",ja:"質問があれば、チャットに書いてください。"},
   {hi:"अब मैं आज की वक्ता का परिचय देता हूँ।",rom:"ab maiṁ āj kī vaktā kā parichay detā hūṁ.",ja:"では、今日話してくださる方をご紹介します。"},
   {hi:"नेहा जी दिल्ली में रहती हैं। वे नौकरी और परिवार के साथ हर दिन पढ़ाई भी करती हैं।",rom:"Nehā jī Dillī meṁ rahtī haiṁ. ve naukarī aur parivār ke sāth har din paṛhāī bhī kartī haiṁ.",ja:"ネハさんはデリーに住んでいます。仕事と家族のことをしながら、毎日勉強も続けています。"},
   {hi:"जो इंसान इतना कुछ एक साथ करता है, उससे हम सबको बहुत कुछ सीखना चाहिए।",rom:"jo insān itnā kuchh ek sāth kartā hai, usse ham sabko bahut kuchh sīkhnā chāhie.",ja:"これだけのことを一度にこなしている人から、私たちは多くを学べるはずです。"},
   {hi:"नेहा जी, आपका स्वागत है। स्क्रीन आपकी है।",rom:"Nehā jī, āpkā svāgat hai. skrīn āpkī hai.",ja:"ネハさん、ようこそ。画面をお渡しします。"},
   {hi:"धन्यवाद नेहा जी, बहुत अच्छी बातें थीं।",rom:"dhanyavād Nehā jī, bahut achchhī bāteṁ thīṁ.",ja:"ネハさん、ありがとうございました。とてもいいお話でした。"},
   {hi:"अब सवाल-जवाब का समय है। क्या किसी का कोई सवाल है?",rom:"ab savāl-javāb kā samay hai. kyā kisī kā koī savāl hai?",ja:"では、質問の時間です。どなたか質問はありますか。"},
   {hi:"अर्जुन जी, आपका हाथ उठा है। बोलिए।",rom:"Arjun jī, āpkā hāth uṭhā hai. bolie.",ja:"アルジュンさん、手が挙がっていますね。どうぞ。"},
   {hi:"बहुत अच्छा सवाल है, धन्यवाद। नेहा जी, क्या आप इसका जवाब देंगी?",rom:"bahut achchhā savāl hai, dhanyavād. Nehā jī, kyā āp iskā javāb deṁgī?",ja:"とてもいい質問です、ありがとうございます。ネハさん、お答えいただけますか。"},
   {hi:"चलिए, अब सारांश। आज हमने तीन बातें सीखीं।",rom:"chalie, ab sārānsh. āj hamne tīn bāteṁ sīkhīṁ.",ja:"では、まとめです。今日は3つのことを学びました。"},
   {hi:"पहली, सुबह का समय सबसे क़ीमती है। दूसरी, हमें दिन की योजना पहले बनानी चाहिए। तीसरी, आराम भी काम का हिस्सा है।",rom:"pahlī, subah kā samay sabse qīmatī hai. dūsrī, hameṁ din kī yojnā pahle banānī chāhie. tīsrī, ārām bhī kām kā hissā hai.",ja:"1つ目、朝の時間がいちばん大切。2つ目、1日の計画は先に立てるべき。3つ目、休むことも仕事のうち。"},
   {hi:"हमें एक-दूसरे से ऐसे ही सीखते रहना चाहिए।",rom:"hameṁ ek-dūsre se aise hī sīkhte rahnā chāhie.",ja:"これからも、こうしてお互いから学び続けていきましょう。"},
   {hi:"आज के लिए बस इतना ही। अंत तक सुनने के लिए आप सबका धन्यवाद।",rom:"āj ke lie bas itnā hī. ant tak sunne ke lie āp sabkā dhanyavād.",ja:"今日はここまでです。最後まで聞いてくださって、ありがとうございました。"},
   {hi:"अगले महीने फिर मिलेंगे। अपना ध्यान रखिए। नमस्ते!",rom:"agle mahīne phir mileṁge. apnā dhyān rakhie. namaste!",ja:"また来月お会いしましょう。お体に気をつけて。さようなら！"}
  ]},
  task:"インドの仲間のオンライン勉強会で、司会を通して務める（自分の話す部分の合計で3分30秒）。音の確認 → 開会のあいさつ → テーマと進め方 → お願い → 話す人の紹介 → 質問の受けつけ → 3つのまとめ → 締めと次回の予告。",
  taskEn:"Host an online study session for your Indian friends in Hindi (about 3.5 minutes of your own speaking in total). Check the audio, welcome everyone, explain the topic and schedule, make one polite request, introduce the speaker, take questions, summarize three points, and close with thanks and the next date.",
  qa:[
   {q:"क्या इस सत्र की रिकॉर्डिंग मिलेगी?",qRom:"kyā is satr kī rikorḍing milegī?",a:"जी हाँ, सत्र के बाद हम रिकॉर्डिंग और नोट्स ग्रुप में भेजेंगे।",aRom:"jī hāṁ, satr ke bād ham rikorḍing aur noṭs grup meṁ bhejeṁge.",ja:"今日の会の録画はもらえますか。／はい、会のあとで録画とメモをグループに送ります。"},
   {q:"अगला सत्र कब होगा?",qRom:"aglā satr kab hogā?",a:"अगला सत्र अगले महीने इसी समय होगा। तारीख़ मैं ग्रुप में बताऊँगा।",aRom:"aglā satr agle mahīne isī samay hogā. tārīkh maiṁ grup meṁ batāūṁgā.",ja:"次の会はいつですか。／来月の同じ時間です。日にちはグループでお知らせします。"},
   {q:"मुझे सबके सामने बोलने में झिझक होती है। मैं क्या करूँ?",qRom:"mujhe sabke sāmne bolne meṁ jhijhak hotī hai. maiṁ kyā karūṁ?",a:"चिंता मत कीजिए, मुझे भी होती है। पहले छोटे समूह में बोलिए, फिर धीरे-धीरे आदत हो जाएगी।",aRom:"chintā mat kījie, mujhe bhī hotī hai. pahle chhoṭe samūh meṁ bolie, phir dhīre-dhīre ādat ho jāegī.",ja:"みんなの前で話すのが恥ずかしいです。どうしたらいいですか。／心配いりません、私もです。まず小さなグループで話してみて、だんだん慣れていきましょう。"}
  ],
  check:[
   "最初に声が届いているかを確かめたか",
   "テーマと時間の流れを、話の前に伝えられたか",
   "話す人を、名前とがんばり1つで紹介できたか",
   "質問のあと、まず धन्यवाद と感謝できたか",
   "まとめを3つにして、次回の予告で締められたか"
  ],
  slide:"1枚目に「今日のテーマ」と時間の流れ（20分・話し合い・質問）を書き、最後の1枚に3つのまとめと次回の日にちを書きます。"},

 {week:37, level:"A2", length:"3分30秒", title:"日本と愛媛を紹介する（受け身の入口）",
  skill:"受け身 -या जाता है と … के लिए मशहूर है を使って、日本の食と習慣、愛媛のみかん・道後温泉、大洲の城と肱川の鵜飼いを、取引先に紹介できるようになる。",
  lesson:[
   "インドの取引先は、日本のことをよく知りたがっています。とくにホテルやレストランの方には、日本のお客様の習慣を知ることが、そのまま仕事に役立ちます。この週は「日本では〜されます」という受け身 -या जाता है を使って、日本と自分のふるさとを紹介します。",
   "受け身は、だれがするかを言わずに「そういうものです」と説明する形です。जापान में झुककर अभिवादन किया जाता है（日本ではお辞儀であいさつします）。食べられる物・作られる物の男女と数に合わせて、खाया जाता है・खाई जाती है・उगाए जाते हैं と2か所を変えるのを忘れないようにしましょう。",
   "紹介は「大きい → 小さい」の順にすると、地図が頭に浮かびます。日本 → 愛媛 → 大洲。愛媛は एहिमे अपने संतरों के लिए मशहूर है（みかんで有名）、道後温泉は「日本で最も古い温泉の一つ」、大洲は川のそばのお城と、夏の夜の鵜飼い。1つの場所に1つの絵を描くつもりで話します。",
   "最後は、紹介を相手の仕事につなげます。「お辞儀・きれいさ・敬意」は、そのまま日本のおもてなしの土台です。そして अगर आप कभी जापान आएँ, तो…（もし日本に来ることがあれば…）と、自分のふるさとに招いて締めましょう。"
  ],
  structure:[
   {hi:"जापान",rom:"Jāpān",ja:"日本の全体と季節"},
   {hi:"खाना और आदतें",rom:"khānā aur ādateṁ",ja:"食べ物と習慣（受け身）"},
   {hi:"एहिमे",rom:"Ehime",ja:"愛媛（みかん・道後温泉）"},
   {hi:"ओज़ू",rom:"Ozū",ja:"大洲（城・肱川の鵜飼い）"},
   {hi:"निमंत्रण",rom:"nimantraṇ",ja:"おもてなしにつなげて、招いて締める"}
  ],
  phrases:[
   {hi:"जापान एक छोटा-सा द्वीप देश है।",rom:"Jāpān ek chhoṭā-sā dvīp desh hai.",ja:"日本は小さな島国です。",note:"छोटा-सा ＝小さめの、ちょっとした。"},
   {hi:"जापान में बहुत मछली खाई जाती है।",rom:"Jāpān meṁ bahut machhlī khāī jātī hai.",ja:"日本では魚がよく食べられます。",note:"मछली（女）なので खाई जाती है。"},
   {hi:"जापान में झुककर अभिवादन किया जाता है।",rom:"Jāpān meṁ jhukkar abhivādan kiyā jātā hai.",ja:"日本では、お辞儀をしてあいさつします。",note:"करना の受け身は किया जाता है。"},
   {hi:"घर में घुसने से पहले जूते उतारे जाते हैं।",rom:"ghar meṁ ghusne se pahle jūte utāre jāte haiṁ.",ja:"家に入る前に、靴を脱ぎます。",note:"जूते（男・複数）なので उतारे जाते हैं。"},
   {hi:"एहिमे अपने संतरों के लिए मशहूर है।",rom:"Ehime apne santroṁ ke lie mashhūr hai.",ja:"愛媛はみかんで有名です。",note:"… के लिए मशहूर है ＝〜で有名だ。ひとかたまりで覚える。"},
   {hi:"वहाँ बहुत तरह के संतरे उगाए जाते हैं।",rom:"vahāṁ bahut tarah ke santre ugāe jāte haiṁ.",ja:"そこでは、いろいろな種類のみかんが育てられています。",note:"日本から話すなら यहाँ、インドで話すなら वहाँ。"},
   {hi:"ओज़ू में लकड़ी का एक सुंदर क़िला है, जो नदी के पास खड़ा है।",rom:"Ozū meṁ lakṛī kā ek sundar qilā hai, jo nadī ke pās khaṛā hai.",ja:"大洲には、川のそばに建つ、美しい木造のお城があります。",note:"第34週の जो で説明を足す。"},
   {hi:"गर्मियों की रातों में जलकाग की मदद से मछली पकड़ी जाती है।",rom:"garmiyoṁ kī rātoṁ meṁ jalkāg kī madad se machhlī pakṛī jātī hai.",ja:"夏の夜には、鵜を使って魚をとります。",note:"鵜飼いの説明の中心の文。"},
   {hi:"दोगो ओनसेन जापान के सबसे पुराने गर्म पानी के झरनों में से एक है।",rom:"Dogo onsen Jāpān ke sabse purāne garm pānī ke jharnoṁ meṁ se ek hai.",ja:"道後温泉は、日本で最も古い温泉の一つです。",note:"सबसे … में से एक ＝最も〜なものの一つ。"},
   {hi:"अगर आप कभी जापान आएँ, तो एहिमे ज़रूर आइए।",rom:"agar āp kabhī Jāpān āeṁ, to Ehime zarūr āie.",ja:"もし日本に来ることがあれば、ぜひ愛媛に来てください。",note:"第33週の अगर…तो。招きの締めに。"}
  ],
  model:{title:"日本と愛媛・大洲のご紹介（インドのホテルの方へ）", time:"3分30秒", note:"名所の説明は、自分の言葉で短く言いかえてもかまいません。鵜飼いの時期（夏）は、話す前に今年の予定を確かめましょう。", lines:[
   {hi:"नमस्ते शर्मा जी, नमस्ते प्रिया जी। आज मैं आपको अपने देश और अपने इलाक़े के बारे में बताना चाहता हूँ।",rom:"namaste Sharmā jī, namaste Priyā jī. āj maiṁ āpko apne desh aur apne ilāqe ke bāre meṁ batānā chāhtā hūṁ.",ja:"シャルマさん、プリヤさん、こんにちは。今日は、私の国と私の地域についてお話ししたいと思います。"},
   {hi:"जब जापानी मेहमान आपके होटल में आते हैं, तब उनकी आदतें जानना काम आता है।",rom:"jab jāpānī mehmān āpke hoṭal meṁ āte haiṁ, tab unkī ādateṁ jānnā kām ātā hai.",ja:"日本のお客様がホテルに来るとき、その習慣を知っていると役に立ちます。"},
   {hi:"पहले, जापान। जापान एक छोटा-सा द्वीप देश है, जहाँ चार ऋतुएँ बहुत साफ़ महसूस होती हैं।",rom:"pahle, Jāpān. Jāpān ek chhoṭā-sā dvīp desh hai, jahāṁ chār ritueṁ bahut sāf mahsūs hotī haiṁ.",ja:"まず日本です。日本は小さな島国で、四季がはっきり感じられます。"},
   {hi:"वसंत में साकुरा के फूल खिलते हैं, और लोग पेड़ों के नीचे खाना खाते हैं।",rom:"vasant meṁ sākurā ke phūl khilte haiṁ, aur log peṛoṁ ke nīche khānā khāte haiṁ.",ja:"春には桜が咲き、人々は木の下でごはんを食べます。"},
   {hi:"अब खाने की बात। जापान में बहुत मछली खाई जाती है, और चावल हर दिन खाया जाता है।",rom:"ab khāne kī bāt. Jāpān meṁ bahut machhlī khāī jātī hai, aur chāval har din khāyā jātā hai.",ja:"次は食べ物です。日本では魚がよく食べられ、お米は毎日食べられています。"},
   {hi:"सुशी चावल और कच्ची मछली से बनाई जाती है। खाना चॉपस्टिक से खाया जाता है।",rom:"sushī chāval aur kachchī machhlī se banāī jātī hai. khānā chopsṭik se khāyā jātā hai.",ja:"すしは、ごはんと生の魚で作られます。食事はお箸で食べます。"},
   {hi:"कुछ आदतें भी बताता हूँ। जापान में झुककर अभिवादन किया जाता है।",rom:"kuchh ādateṁ bhī batātā hūṁ. Jāpān meṁ jhukkar abhivādan kiyā jātā hai.",ja:"習慣もいくつかお話しします。日本では、お辞儀をしてあいさつします。"},
   {hi:"और घर में घुसने से पहले जूते उतारे जाते हैं। कई पुराने होटलों में भी ऐसा ही होता है।",rom:"aur ghar meṁ ghusne se pahle jūte utāre jāte haiṁ. kaī purāne hoṭaloṁ meṁ bhī aisā hī hotā hai.",ja:"それから、家に入る前に靴を脱ぎます。古い旅館の多くでも同じです。"},
   {hi:"अब मेरा इलाक़ा, एहिमे। एहिमे जापान के शिकोकू द्वीप पर है।",rom:"ab merā ilāqā, Ehime. Ehime Jāpān ke Shikokū dvīp par hai.",ja:"次は私の地域、愛媛です。愛媛は、日本の四国という島にあります。"},
   {hi:"एहिमे अपने संतरों के लिए मशहूर है। वहाँ बहुत तरह के संतरे उगाए जाते हैं।",rom:"Ehime apne santroṁ ke lie mashhūr hai. vahāṁ bahut tarah ke santre ugāe jāte haiṁ.",ja:"愛媛はみかんで有名です。いろいろな種類のみかんが育てられています。"},
   {hi:"सर्दियों में हर दुकान में संतरे दिखते हैं, और संतरे का जूस भी बहुत पिया जाता है।",rom:"sardiyoṁ meṁ har dukān meṁ santre dikhte haiṁ, aur santre kā jūs bhī bahut piyā jātā hai.",ja:"冬にはどの店にもみかんが並び、みかんジュースもよく飲まれています。"},
   {hi:"एहिमे के मात्सुयामा शहर में दोगो ओनसेन है।",rom:"Ehime ke Mātsuyāmā shahar meṁ Dogo onsen hai.",ja:"愛媛の松山市には、道後温泉があります。"},
   {hi:"यह जापान के सबसे पुराने गर्म पानी के झरनों में से एक है।",rom:"yah Jāpān ke sabse purāne garm pānī ke jharnoṁ meṁ se ek hai.",ja:"日本で最も古い温泉の一つです。"},
   {hi:"ओनसेन में लोग गर्म पानी में बैठकर आराम करते हैं।",rom:"onsen meṁ log garm pānī meṁ baiṭhkar ārām karte haiṁ.",ja:"温泉では、人々はお湯につかって、ゆっくり休みます。"},
   {hi:"अब मेरा शहर, ओज़ू। मेरा क्लिनिक वहीं है।",rom:"ab merā shahar, Ozū. merā klinik vahīṁ hai.",ja:"そして私の町、大洲です。私の院は、まさにそこにあります。"},
   {hi:"ओज़ू में लकड़ी का एक सुंदर क़िला है, जो नदी के पास खड़ा है।",rom:"Ozū meṁ lakṛī kā ek sundar qilā hai, jo nadī ke pās khaṛā hai.",ja:"大洲には、川のそばに建つ、美しい木造のお城があります。"},
   {hi:"उस नदी का नाम हिजीकावा है। गर्मियों की रातों में वहाँ उकाई होता है।",rom:"us nadī kā nām Hijikāvā hai. garmiyoṁ kī rātoṁ meṁ vahāṁ ukāī hotā hai.",ja:"その川の名前は肱川です。夏の夜、そこで鵜飼いが行われます。"},
   {hi:"उकाई में नाव से, जलकाग की मदद से मछली पकड़ी जाती है।",rom:"ukāī meṁ nāv se, jalkāg kī madad se machhlī pakṛī jātī hai.",ja:"鵜飼いでは、舟の上から、鵜を使って魚をとります。"},
   {hi:"मछुआरे आग की रोशनी में काम करते हैं। यह देखने में बहुत सुंदर लगता है।",rom:"machhuāre āg kī roshnī meṁ kām karte haiṁ. yah dekhne meṁ bahut sundar lagtā hai.",ja:"鵜匠はかがり火の明かりの中で仕事をします。見ていて、とても美しい光景です。"},
   {hi:"जापान में यह परंपरा बहुत पुरानी है। मेहमान नाव में बैठकर इसे पास से देखते हैं।",rom:"Jāpān meṁ yah paramparā bahut purānī hai. mehmān nāv meṁ baiṭhkar ise pās se dekhte haiṁ.",ja:"日本では、とても古い伝統です。お客様は舟に乗って、近くから見物します。"},
   {hi:"संक्षेप में, जापान में सम्मान और सफ़ाई को बहुत महत्व दिया जाता है।",rom:"sankshep meṁ, Jāpān meṁ sammān aur safāī ko bahut mahatva diyā jātā hai.",ja:"まとめると、日本では敬意ときれいさがとても大切にされています。"},
   {hi:"यही बातें जापानी मेहमाननवाज़ी में भी दिखती हैं।",rom:"yahī bāteṁ jāpānī mehmānnavāzī meṁ bhī dikhtī haiṁ.",ja:"それは、日本のおもてなしにもそのまま表れています。"},
   {hi:"अगर आप कभी जापान आएँ, तो एहिमे और ओज़ू ज़रूर आइए। मैं ख़ुद आपको घुमाऊँगा। धन्यवाद!",rom:"agar āp kabhī Jāpān āeṁ, to Ehime aur Ozū zarūr āie. maiṁ khud āpko ghumāūṁgā. dhanyavād!",ja:"もし日本に来ることがあれば、ぜひ愛媛と大洲へ。私が自分でご案内します。ありがとうございました！"}
  ]},
  task:"インドのホテル・レストランの取引先に、日本 → 愛媛 → 大洲 の順で3分30秒の紹介をする。受け身 -या जाता है を5回以上、… के लिए मशहूर है を1回使い、最後はおもてなしにつなげて、ふるさとに招いて締める。",
  taskEn:"Give a 3.5-minute presentation in Hindi to Indian hotel and restaurant partners introducing Japan, then Ehime, then Ozu. Use the passive (-या जाता है) at least five times and … के लिए मशहूर है once. Connect the customs to Japanese hospitality and end by inviting them to visit.",
  qa:[
   {q:"क्या जापान में शाकाहारी खाना आसानी से मिलता है?",qRom:"kyā Jāpān meṁ shākāhārī khānā āsānī se miltā hai?",a:"बड़े शहरों में मिलता है, लेकिन छोटे शहरों में थोड़ा मुश्किल है। पहले से बताना अच्छा रहता है।",aRom:"baṛe shahroṁ meṁ miltā hai, lekin chhoṭe shahroṁ meṁ thoṛā mushkil hai. pahle se batānā achchhā rahtā hai.",ja:"日本ではベジタリアンの食事は見つけやすいですか。／大きな町ではありますが、小さな町では少し難しいです。前もって伝えておくと安心です。"},
   {q:"उकाई देखने का सबसे अच्छा समय कब है?",qRom:"ukāī dekhne kā sabse achchhā samay kab hai?",a:"गर्मियों में, जून से सितंबर तक। शाम के बाद नाव से देखा जाता है।",aRom:"garmiyoṁ meṁ, jūn se sitambar tak. shām ke bād nāv se dekhā jātā hai.",ja:"鵜飼いを見るのにいちばんいい時期はいつですか。／夏、6月から9月までです。夕方から、舟に乗って見物します。"},
   {q:"एहिमे जाने के लिए सबसे पास का एयरपोर्ट कौन-सा है?",qRom:"Ehime jāne ke lie sabse pās kā eyarporṭ kaun-sā hai?",a:"मात्सुयामा एयरपोर्ट। टोक्यो या ओसाका से वहाँ सीधी फ़्लाइट है।",aRom:"Mātsuyāmā eyarporṭ. Ṭokyo yā Osākā se vahāṁ sīdhī flāiṭ hai.",ja:"愛媛に行くには、どの空港がいちばん近いですか。／松山空港です。東京か大阪から直行便があります。"}
  ],
  check:[
   "受け身の2か所（khāī jātī・ugāe jāte など）を、物の男女と数にそろえられたか",
   "日本 → 愛媛 → 大洲 の順で、地図が浮かぶように話せたか",
   "… ke lie mashhūr hai を使えたか",
   "紹介を、日本のお客様の習慣・おもてなしにつなげられたか",
   "最後に agar…to で、相手を招いて締められたか"
  ],
  slide:"日本・愛媛・大洲の地図を1枚、写真はみかん・道後温泉・大洲城・鵜飼いの4枚を大きく。文字は地名だけにします。"},

 {week:38, level:"A2", length:"3分30秒", title:"つかみの話で始める（クリケット・映画）",
  skill:"クリケットや映画の身近な話題を「つかみ」にして、मुझे लगता है कि（〜と思う）と経験の -ा है で自分の考えにつなげ、仲間の前で3分30秒のスピーチができるようになる。",
  lesson:[
   "インドの仲間の前では、最初の30秒で心をつかむと、あとの話がぐっと届きやすくなります。クリケットと映画は、インドでいちばん盛り上がる話題です。「昨日の試合を見た人、手を挙げて！」と聞くだけで、場が一気にあたたまります。",
   "くわしくなくても大丈夫です。सच कहूँ तो, मुझे नियम ठीक से समझ नहीं आते（正直、ルールはまだよくわかりません）と正直に言うと、笑いが起きて、親しみがわきます。そのあと「でも、一つ好きなところがあります」と、自分の見方につなげましょう。",
   "つかみは、本題への橋です。「いいバッターは毎球シックスを打たない。いい球を待つ」→ मुझे लगता है कि हमारी ज़िंदगी भी ऐसी ही है（私たちの人生も同じだと思います）。たとえ話から学びを1つ取り出し、自分の経験（ヒンディー語の勉強など）で裏づけます。",
   "映画の話をするときは、有名な台詞をそのまま引用せず、自分の言葉で「インドの映画では、うれしい場面でみんなで歌って踊る」のように場面を説明します。そこから「小さな成功も一緒に祝おう」と、仲間へのメッセージで締めましょう。試合や映画の経験は、必ず自分の本当の経験を話します。"
  ],
  structure:[
   {hi:"सवाल से शुरुआत",rom:"savāl se shuruāt",ja:"問いかけでつかむ"},
   {hi:"क्रिकेट की बात",rom:"krikeṭ kī bāt",ja:"クリケットのたとえ"},
   {hi:"सीख",rom:"sīkh",ja:"そこからの学び（मुझे लगता है कि）"},
   {hi:"फ़िल्मों की बात",rom:"filmoṁ kī bāt",ja:"映画の場面から2つ目の学び"},
   {hi:"संदेश",rom:"sandesh",ja:"仲間へのメッセージと締め"}
  ],
  phrases:[
   {hi:"हाथ उठाइए, कल का मैच किसने देखा?",rom:"hāth uṭhāie, kal kā maich kisne dekhā?",ja:"昨日の試合を見た人、手を挙げてください！",note:"見た ＝ने 構文なので किसने。つかみの定番。"},
   {hi:"क्या आपने कभी स्टेडियम में मैच देखा है?",rom:"kyā āpne kabhī sṭeḍiyam meṁ maich dekhā hai?",ja:"スタジアムで試合を見たことはありますか。",note:"कभी … देखा है? ＝今までに〜したことがありますか。"},
   {hi:"सच कहूँ तो, मुझे क्रिकेट के नियम अभी ठीक से समझ नहीं आते।",rom:"sach kahūṁ to, mujhe krikeṭ ke niyam abhī ṭhīk se samajh nahīṁ āte.",ja:"正直に言うと、クリケットのルールはまだよくわかりません。",note:"सच कहूँ तो は決まり文句として覚える。正直さが笑いと親しみを生む。"},
   {hi:"मैंने टीवी पर कई मैच देखे हैं।",rom:"maiṁne ṭīvī par kaī maich dekhe haiṁ.",ja:"テレビで何試合も見たことがあります。",note:"मैच（男・複数）なので देखे हैं。自分の本当の経験に合わせる。"},
   {hi:"मुझे लगता है कि क्रिकेट और ज़िंदगी में बहुत समानता है।",rom:"mujhe lagtā hai ki krikeṭ aur zindagī meṁ bahut samāntā hai.",ja:"クリケットと人生には、似ているところがたくさんあると思います。",note:"मुझे लगता है कि ＋ふつうの文。つかみから本題への橋。"},
   {hi:"अच्छा बल्लेबाज़ हर गेंद पर छक्का नहीं मारता।",rom:"achchhā ballebāz har gend par chhakkā nahīṁ mārtā.",ja:"いいバッターは、毎球シックスを打つわけではありません。",note:"छक्का मारना ＝シックスを打つ。"},
   {hi:"वह सही गेंद का इंतज़ार करता है।",rom:"vah sahī gend kā intazār kartā hai.",ja:"いい球が来るのを待つのです。",note:"… का इंतज़ार करना ＝〜を待つ。"},
   {hi:"मैंने कुछ हिंदी फ़िल्में देखी हैं।",rom:"maiṁne kuchh hindī filmeṁ dekhī haiṁ.",ja:"ヒンディー語の映画を何本か見たことがあります。",note:"फ़िल्में（女・複数）なので देखी हैं。"},
   {hi:"छोटी जीत का भी जश्न मनाइए।",rom:"chhoṭī jīt kā bhī jashn manāie.",ja:"小さな勝ちも、お祝いしましょう。",note:"जश्न मनाना ＝祝う。締めのメッセージに。"},
   {hi:"तो आज की बात यही है।",rom:"to āj kī bāt yahī hai.",ja:"というわけで、今日お伝えしたいのはこれです。",note:"つかみから本題をまとめる合図。"}
  ],
  model:{title:"クリケットと映画から学ぶこと（仲間の集まりで）", time:"3分30秒", note:"試合や映画を見た経験は、自分の本当の経験に入れかえましょう。映画の台詞は引用せず、場面を自分の言葉で話します。", lines:[
   {hi:"नमस्ते दोस्तों! शुरू करने से पहले एक सवाल।",rom:"namaste doston! shurū karne se pahle ek savāl.",ja:"皆さん、こんにちは！始める前に、一つ質問です。"},
   {hi:"हाथ उठाइए, कल का भारत का मैच किसने देखा?",rom:"hāth uṭhāie, kal kā Bhārat kā maich kisne dekhā?",ja:"昨日のインドの試合を見た人、手を挙げてください！"},
   {hi:"वाह, लगभग सबने! भारत में सबको क्रिकेट बहुत पसंद है, यह मुझे अच्छी तरह पता है।",rom:"vāh, lagbhag sabne! Bhārat meṁ sabko krikeṭ bahut pasand hai, yah mujhe achchhī tarah patā hai.",ja:"わあ、ほとんど全員ですね！インドでは皆さんがクリケット好きなこと、よく知っています。"},
   {hi:"सच कहूँ तो, मुझे क्रिकेट के नियम अभी ठीक से समझ नहीं आते।",rom:"sach kahūṁ to, mujhe krikeṭ ke niyam abhī ṭhīk se samajh nahīṁ āte.",ja:"正直に言うと、私はクリケットのルールがまだよくわかりません。"},
   {hi:"लेकिन मैंने टीवी पर कई मैच देखे हैं, और एक बात मुझे बहुत अच्छी लगती है।",rom:"lekin maiṁne ṭīvī par kaī maich dekhe haiṁ, aur ek bāt mujhe bahut achchhī lagtī hai.",ja:"でも、テレビで何試合も見たことがあって、一つとても好きなところがあります。"},
   {hi:"अच्छा बल्लेबाज़ हर गेंद पर छक्का नहीं मारता।",rom:"achchhā ballebāz har gend par chhakkā nahīṁ mārtā.",ja:"いいバッターは、毎球シックスを打つわけではありません。"},
   {hi:"कभी वह गेंद छोड़ देता है, कभी सिर्फ़ एक रन लेता है।",rom:"kabhī vah gend chhoṛ detā hai, kabhī sirf ek ran letā hai.",ja:"球を見送ることもあれば、1点だけ取ることもあります。"},
   {hi:"वह सही गेंद का इंतज़ार करता है, और फिर पूरी ताक़त से खेलता है।",rom:"vah sahī gend kā intazār kartā hai, aur phir pūrī tāqat se kheltā hai.",ja:"いい球が来るのを待って、そのとき全力で打つのです。"},
   {hi:"मुझे लगता है कि हमारी ज़िंदगी भी ऐसी ही है।",rom:"mujhe lagtā hai ki hamārī zindagī bhī aisī hī hai.",ja:"私たちの人生も、同じだと思います。"},
   {hi:"हर दिन बड़ा दिन नहीं होता। कई दिन बस एक-एक रन जोड़ने वाले होते हैं।",rom:"har din baṛā din nahīṁ hotā. kaī din bas ek-ek ran joṛne vāle hote haiṁ.",ja:"毎日が大きな日ではありません。1点ずつ積み重ねるだけの日も、たくさんあります。"},
   {hi:"मैं हिंदी सीख रहा हूँ। कुछ दिन सिर्फ़ पाँच नए शब्द याद होते हैं।",rom:"maiṁ hindī sīkh rahā hūṁ. kuchh din sirf pāṁch nae shabd yād hote haiṁ.",ja:"私はヒンディー語を学んでいます。新しい単語を5つしか覚えられない日もあります。"},
   {hi:"लेकिन वही एक-एक रन जुड़कर बड़ा स्कोर बनता है।",rom:"lekin vahī ek-ek ran juṛkar baṛā skor bantā hai.",ja:"でも、その1点1点が積み重なって、大きなスコアになるのです。"},
   {hi:"और एक बात। क्रिकेट में अकेला खिलाड़ी मैच नहीं जीतता। साझेदारी चाहिए।",rom:"aur ek bāt. krikeṭ meṁ akelā khilāṛī maich nahīṁ jīttā. sājhedārī chāhie.",ja:"もう一つあります。クリケットでは、一人の選手だけでは試合に勝てません。パートナーシップが必要です。"},
   {hi:"दो बल्लेबाज़ एक-दूसरे पर भरोसा करते हैं, और साथ में दौड़ते हैं।",rom:"do ballebāz ek-dūsre par bharosā karte haiṁ, aur sāth meṁ dauṛte haiṁ.",ja:"2人のバッターはお互いを信じて、一緒に走ります。"},
   {hi:"हमारा यह ग्रुप भी एक टीम है। जब कोई थक जाए, तब दूसरा साथ देता है।",rom:"hamārā yah grup bhī ek ṭīm hai. jab koī thak jāe, tab dūsrā sāth detā hai.",ja:"私たちのこのグループも、一つのチームです。だれかが疲れたら、ほかのだれかが支えます。"},
   {hi:"अब फ़िल्मों की बात। मैंने कुछ हिंदी फ़िल्में देखी हैं, और मुझे उनके गाने बहुत पसंद हैं।",rom:"ab filmoṁ kī bāt. maiṁne kuchh hindī filmeṁ dekhī haiṁ, aur mujhe unke gāne bahut pasand haiṁ.",ja:"次は映画の話です。ヒンディー語の映画を何本か見たことがあって、歌がとても好きです。"},
   {hi:"हिंदी फ़िल्मों में ख़ुशी के मौक़े पर सब मिलकर नाचते-गाते हैं।",rom:"hindī filmoṁ meṁ khushī ke mauqe par sab milkar nāchte-gāte haiṁ.",ja:"インドの映画では、うれしい場面で、みんなで一緒に歌って踊りますよね。"},
   {hi:"मुझे लगता है कि यह भी एक अच्छी सीख है। छोटी जीत का भी जश्न मनाइए।",rom:"mujhe lagtā hai ki yah bhī ek achchhī sīkh hai. chhoṭī jīt kā bhī jashn manāie.",ja:"これも大切な学びだと思います。小さな勝ちも、お祝いしましょう。"},
   {hi:"अगर किसी ने इस हफ़्ते कुछ नया सीखा, तो उसके लिए ताली बजाइए!",rom:"agar kisī ne is hafte kuchh nayā sīkhā, to uske lie tālī bajāie!",ja:"今週、何か新しいことを学んだ人がいたら、その人に拍手を！"},
   {hi:"तो आज की बात यही है। धीरज रखिए, एक-दूसरे का साथ दीजिए, और छोटी ख़ुशियाँ मनाइए।",rom:"to āj kī bāt yahī hai. dhīraj rakhie, ek-dūsre kā sāth dījie, aur chhoṭī khushiyāṁ manāie.",ja:"というわけで、今日お伝えしたいのはこれです。気長に、お互いを支え合い、小さな喜びをお祝いしましょう。"},
   {hi:"बहुत-बहुत धन्यवाद। और हाँ, अगले मैच में भारत ही जीतेगा, मुझे पूरा भरोसा है!",rom:"bahut-bahut dhanyavād. aur hāṁ, agle maich meṁ Bhārat hī jītegā, mujhe pūrā bharosā hai!",ja:"ありがとうございました。それから、次の試合はインドが勝ちますよ、間違いなし！"}
  ]},
  task:"インドの仲間の集まりで、クリケットか映画の話をつかみにした3分30秒のスピーチをする。問いかけで始め、正直なひと言で笑いをとり、मुझे लगता है कि で学びを2つ取り出し、自分の経験で裏づけ、仲間へのメッセージで締める。映画の台詞は引用しない。",
  taskEn:"Give a 3.5-minute speech in Hindi to your Indian friends that opens with a hook about cricket or films. Start with a question to the audience, admit honestly how much you know, draw two lessons with मुझे लगता है कि, support them with your own experience, and end with a message to the group. Do not quote real film dialogue.",
  qa:[
   {q:"आपका पसंदीदा खिलाड़ी कौन है?",qRom:"āpkā pasandīdā khilāṛī kaun hai?",a:"सच कहूँ तो, अभी मेरा कोई पसंदीदा खिलाड़ी नहीं है। आप बताइए, मुझे किसका मैच देखना चाहिए?",aRom:"sach kahūṁ to, abhī merā koī pasandīdā khilāṛī nahīṁ hai. āp batāie, mujhe kiskā maich dekhnā chāhie?",ja:"好きな選手はだれですか。／正直に言うと、まだいないんです。教えてください、だれの試合を見たらいいですか。"},
   {q:"क्या आपने कभी स्टेडियम में मैच देखा है?",qRom:"kyā āpne kabhī sṭeḍiyam meṁ maich dekhā hai?",a:"नहीं, अभी तक नहीं देखा। अगली बार भारत आऊँ, तो ज़रूर देखना चाहता हूँ।",aRom:"nahīṁ, abhī tak nahīṁ dekhā. aglī bār Bhārat āūṁ, to zarūr dekhnā chāhtā hūṁ.",ja:"スタジアムで試合を見たことはありますか。／いいえ、まだありません。次にインドに来たら、ぜひ見たいです。"},
   {q:"जापान में कौन-सा खेल सबसे ज़्यादा पसंद किया जाता है?",qRom:"Jāpān meṁ kaun-sā khel sabse zyādā pasand kiyā jātā hai?",a:"मुझे लगता है कि बेसबॉल और फ़ुटबॉल सबसे ज़्यादा पसंद किए जाते हैं।",aRom:"mujhe lagtā hai ki besbol aur fuṭbol sabse zyādā pasand kie jāte haiṁ.",ja:"日本ではどのスポーツがいちばん人気ですか。／野球とサッカーがいちばん人気だと思います。"}
  ],
  check:[
   "最初の30秒で、聞き手に問いかけられたか",
   "maiṁne … dekhā hai / dekhī haiṁ を、見た物の男女と数にそろえられたか",
   "mujhe lagtā hai ki で、つかみから学びにつなげられたか",
   "自分の本当の経験で学びを裏づけられたか",
   "映画の台詞を引用せず、自分の言葉で場面を説明できたか"
  ],
  slide:"最初の1枚はクリケットのバットとボールの写真だけ。最後の1枚に「धीरज・साथ・ख़ुशी」の3語を大きく出します。"},

 {week:39, level:"A2", length:"4分", title:"第3期の発表：4分の会社・事業紹介",
  skill:"第3期で練習した表現（-ने से पहले/बाद、जो…वह、अगर…तो、受け身、मुझे लगता है कि）を1つにまとめ、取引先に4分の会社・事業紹介をして、次の一歩まで話せるようになる。",
  lesson:[
   "第3期のしめくくりは、4分の会社・事業紹介です。流れは、あいさつと目的 → 4つの話の予告 → 自分の経歴 → 4つの事業 → 相手にとっての良さ → 大切にしていること → まとめ → 次の一歩。これまで13週で練習した表現を、1つの話にまとめます。",
   "最初の30秒で「今日の目的」を言いましょう。आज की मीटिंग का मक़सद है…（今日の目的は…）と言い、「4分で4つお話しします」と地図を渡します。経歴は -ने से पहले/बाद（院を開く前は…・開いた後は…）、事業は जो…वह でくわしく、が今期の型です。",
   "相手にとっての良さは、अगर…तो で具体的に話します。「もし日本のお客様が来るなら、こんな点に気をつけています」と、相手の毎日の場面を描くと、聞き手は自分ごととして聞いてくれます。費用や細かい条件は、विस्तार की बातें हम अंग्रेज़ी में कर सकते हैं と英語に切り替えてかまいません。",
   "本番の前に、4分を計って3回通しで練習し、録音を聞いて、早口になった所・言葉につまった所に印をつけましょう。完璧なヒンディー語より、落ち着いて相手の目を見て、最後に「目の前の人に全力を尽くす」という自分の言葉を伝えることが、信頼につながります。"
  ],
  structure:[
   {hi:"शुरुआत और मक़सद",rom:"shuruāt aur maqsad",ja:"あいさつ・目的・4つの予告"},
   {hi:"मेरा परिचय",rom:"merā parichay",ja:"経歴（-ने से पहले/बाद）"},
   {hi:"मेरे चार काम",rom:"mere chār kām",ja:"4つの事業（जो…वह）"},
   {hi:"आपके लिए फ़ायदा",rom:"āpke lie fāydā",ja:"相手にとっての良さ（अगर…तो）"},
   {hi:"मेरी सोच",rom:"merī soch",ja:"大切にしていること"},
   {hi:"अगला क़दम",rom:"aglā qadam",ja:"まとめと次の一歩・質問"}
  ],
  phrases:[
   {hi:"आज की मीटिंग का मक़सद है, अपने काम का परिचय देना।",rom:"āj kī mīṭing kā maqsad hai, apne kām kā parichay denā.",ja:"今日のミーティングの目的は、私の仕事をご紹介することです。",note:"मक़सद ＝目的。最初の30秒で言う。"},
   {hi:"मैं चार मिनट में चार बातें बताऊँगा।",rom:"maiṁ chār minaṭ meṁ chār bāteṁ batāūṁgā.",ja:"4分で4つのことをお話しします。",note:"話の地図を先に渡す。"},
   {hi:"क्लिनिक खोलने से पहले मैं स्पोर्ट्स ट्रेनर था।",rom:"klinik kholne se pahle maiṁ sporṭs ṭrenar thā.",ja:"院を開く前は、スポーツのトレーナーでした。",note:"-ने से पहले ＝〜する前に（第27週）。"},
   {hi:"जो सिस्टम मैंने बनाया, उसे आज हमारे साथी क्लिनिक भी इस्तेमाल करते हैं।",rom:"jo sisṭam maiṁne banāyā, use āj hamāre sāthī klinik bhī istemāl karte haiṁ.",ja:"私が作ったシステムを、今は提携院も使っています。",note:"जो…उसे（第34週）。"},
   {hi:"मेरे परिवार की साके की दुकान 1957 से चल रही है।",rom:"mere parivār kī sāke kī dukān 1957 se chal rahī hai.",ja:"家族の酒店は、1957年から続いています。",note:"से चल रही है ＝〜から続いている。"},
   {hi:"अगर आपके होटल में जापानी मेहमान आते हैं, तो मैं आपकी मदद कर सकता हूँ।",rom:"agar āpke hoṭal meṁ jāpānī mehmān āte haiṁ, to maiṁ āpkī madad kar saktā hūṁ.",ja:"もしホテルに日本のお客様が来るなら、私がお手伝いできます。",note:"अगर…तो（第33週）で相手の場面を描く。"},
   {hi:"मुझे लगता है कि हम साथ मिलकर अच्छा काम कर सकते हैं।",rom:"mujhe lagtā hai ki ham sāth milkar achchhā kām kar sakte haiṁ.",ja:"一緒に、いい仕事ができると思います。",note:"मुझे लगता है कि（第38週）。押しつけずに思いを伝える。"},
   {hi:"मेरे लिए सबसे ज़रूरी बात यह है कि जो इंसान सामने है, उसके लिए पूरी कोशिश करूँ।",rom:"mere lie sabse zarūrī bāt yah hai ki jo insān sāmne hai, uske lie pūrī koshish karūṁ.",ja:"私にとっていちばん大切なのは、目の前の人に全力を尽くすことです。",note:"自分の信条。ゆっくり、相手の目を見て言う。"},
   {hi:"अगले क़दम के तौर पर, मैं आपको एक छोटा प्रस्ताव भेजना चाहूँगा।",rom:"agle qadam ke taur par, maiṁ āpko ek chhoṭā prastāv bhejnā chāhūṁgā.",ja:"次の一歩として、小さなご提案をお送りしたいと思います。",note:"के तौर पर ＝〜として。決まり文句として覚える。"},
   {hi:"विस्तार की बातें हम अंग्रेज़ी में कर सकते हैं।",rom:"vistār kī bāteṁ ham angrezī meṁ kar sakte haiṁ.",ja:"細かいお話は、英語でさせていただければと思います。",note:"条件や費用は英語に切り替えてよい。"}
  ],
  model:{title:"アキヒロの会社・事業紹介（インドのホテルの取引先へ）", time:"4分", note:"経歴と事業は事実にそった内容です。次の一歩（来週のミーティングなど）は、相手に合わせて入れかえましょう。", lines:[
   {hi:"नमस्ते शर्मा जी, नमस्ते प्रिया जी। आज समय निकालने के लिए बहुत-बहुत धन्यवाद।",rom:"namaste Sharmā jī, namaste Priyā jī. āj samay nikālne ke lie bahut-bahut dhanyavād.",ja:"シャルマさん、プリヤさん、こんにちは。今日はお時間を作っていただき、本当にありがとうございます。"},
   {hi:"मेरा नाम आकिहिरो इवाता है। मैं जापान के एहिमे से आया हूँ।",rom:"merā nām Ākihiro Ivātā hai. maiṁ Jāpān ke Ehime se āyā hūṁ.",ja:"岩田章弘と申します。日本の愛媛から来ました。"},
   {hi:"आज की मीटिंग का मक़सद है, अपने काम का परिचय देना, और यह देखना कि हम साथ में क्या कर सकते हैं।",rom:"āj kī mīṭing kā maqsad hai, apne kām kā parichay denā, aur yah dekhnā ki ham sāth meṁ kyā kar sakte haiṁ.",ja:"今日の目的は、私の仕事をご紹介し、一緒に何ができるかを考えることです。"},
   {hi:"मैं चार मिनट में चार बातें बताऊँगा। मेरा परिचय, मेरा काम, आपके लिए फ़ायदा, और अगला क़दम।",rom:"maiṁ chār minaṭ meṁ chār bāteṁ batāūṁgā. merā parichay, merā kām, āpke lie fāydā, aur aglā qadam.",ja:"4分で4つお話しします。私の紹介、私の仕事、皆さんにとっての良さ、そして次の一歩です。"},
   {hi:"पहले, मेरा परिचय। मैं मूल रूप से योकोहामा से हूँ।",rom:"pahle, merā parichay. maiṁ mūl rūp se Yokohāmā se hūṁ.",ja:"まず、私の紹介です。出身は横浜です。"},
   {hi:"क्लिनिक खोलने से पहले मैं स्पोर्ट्स ट्रेनर था।",rom:"klinik kholne se pahle maiṁ sporṭs ṭrenar thā.",ja:"院を開く前は、スポーツのトレーナーでした。"},
   {hi:"मैंने हाई स्कूल, यूनिवर्सिटी, कंपनी की टीमों, और प्रोफ़ेशनल टीमों के साथ काम किया।",rom:"maiṁne hāī skūl, yūnivarsiṭī, kampanī kī ṭīmoṁ, aur profeshanal ṭīmoṁ ke sāth kām kiyā.",ja:"高校、大学、実業団、プロのチームで仕事をしてきました。"},
   {hi:"मेरे पास जापान के दो सरकारी लाइसेंस हैं, एक्यूपंक्चर और जूडो थेरेपी।",rom:"mere pās Jāpān ke do sarkārī lāisens haiṁ, ekyūpankchar aur jūḍo therepī.",ja:"日本の国家資格を2つ持っています。鍼灸と柔道整復です。"},
   {hi:"दूसरा, मेरा काम। 2018 में मैंने ओज़ू शहर में अपना क्लिनिक खोला। आज वहाँ चार स्टाफ़ मेरे साथ काम करते हैं।",rom:"dūsrā, merā kām. 2018 meṁ maiṁne Ozū shahar meṁ apnā klinik kholā. āj vahāṁ chār sṭāf mere sāth kām karte haiṁ.",ja:"2つ目は私の仕事です。2018年に大洲市で院を開きました。今は4人のスタッフと一緒に働いています。"},
   {hi:"क्लिनिक खोलने के बाद मैंने हर दिन बिक्री, आने वाले लोगों की संख्या, और दोबारा आने की दर देखना शुरू किया।",rom:"klinik kholne ke bād maiṁne har din bikrī, āne vāle logoṁ kī sankhyā, aur dobārā āne kī dar dekhnā shurū kiyā.",ja:"院を開いた後、毎日、売上・来院数・再来院率を見るようになりました。"},
   {hi:"इसके लिए मैंने बुकिंग और ग्राहकों का रिकॉर्ड रखने का एक सिस्टम बनाया।",rom:"iske lie maiṁne buking aur grāhakoṁ kā rikorḍ rakhne kā ek sisṭam banāyā.",ja:"そのために、予約とお客様の記録を残すシステムを作りました。"},
   {hi:"जो सिस्टम मैंने बनाया, उसे आज हमारे साथी क्लिनिक भी इस्तेमाल करते हैं। मैं उनके मैनेजमेंट में भी मदद करता हूँ।",rom:"jo sisṭam maiṁne banāyā, use āj hamāre sāthī klinik bhī istemāl karte haiṁ. maiṁ unke mainejmenṭ meṁ bhī madad kartā hūṁ.",ja:"私が作ったシステムを、今は提携院も使っています。その院の経営のお手伝いもしています。"},
   {hi:"तीसरा काम भारत से जुड़ा है। मैं भारत की कंपनियों को जापानी मेहमाननवाज़ी की सलाह देता हूँ।",rom:"tīsrā kām Bhārat se juṛā hai. maiṁ Bhārat kī kampaniyoṁ ko jāpānī mehmānnavāzī kī salāh detā hūṁ.",ja:"3つ目の仕事は、インドとつながっています。インドの会社に、日本のおもてなしのコンサルをしています。"},
   {hi:"यह काम उन होटलों, रेस्टोरेंट और क्लिनिक के लिए है, जहाँ जापानी मेहमान आते हैं।",rom:"yah kām un hoṭaloṁ, resṭoranṭ aur klinik ke lie hai, jahāṁ jāpānī mehmān āte haiṁ.",ja:"日本のお客様が来るホテル、レストラン、クリニックのための仕事です。"},
   {hi:"और उन भारतीय मेहमानों के लिए भी, जिन्हें जापान पसंद है।",rom:"aur un bhāratīy mehmānoṁ ke lie bhī, jinheṁ Jāpān pasand hai.",ja:"そして、日本が好きなインドのお客様のためでもあります。"},
   {hi:"चौथा, मेरे परिवार की साके की दुकान, ओदानी साके तेन। यह दुकान 1957 से चल रही है, और मैं इसका इंटरनेशनल काम देखता हूँ।",rom:"chauthā, mere parivār kī sāke kī dukān, Odānī Sāke Ten. yah dukān 1957 se chal rahī hai, aur maiṁ iskā inṭarneshanal kām dekhtā hūṁ.",ja:"4つ目は、家族の酒店、小谷酒店です。1957年から続く店で、私は海外の仕事を担当しています。"},
   {hi:"जापान में ख़ुशी के मौक़ों पर साके पीने की परंपरा है।",rom:"Jāpān meṁ khushī ke mauqoṁ par sāke pīne kī paramparā hai.",ja:"日本には、お祝いの席で日本酒を飲む伝統があります。"},
   {hi:"अब, आपके लिए फ़ायदा। अगर आपके होटल में जापानी मेहमान आते हैं, तो वे छोटी-छोटी बातों पर ध्यान देते हैं।",rom:"ab, āpke lie fāydā. agar āpke hoṭal meṁ jāpānī mehmān āte haiṁ, to ve chhoṭī-chhoṭī bātoṁ par dhyān dete haiṁ.",ja:"次に、皆さんにとっての良さです。もしホテルに日本のお客様が来るなら、そのお客様は細かいところをよく見ています。"},
   {hi:"जैसे सफ़ाई, समय की पाबंदी, और शांत सेवा।",rom:"jaise safāī, samay kī pābandī, aur shānt sevā.",ja:"たとえば、きれいさ、時間を守ること、そして落ち着いたサービスです。"},
   {hi:"अगर स्टाफ़ ये बातें समझ ले, तो मेहमान ख़ुश होकर दोबारा आते हैं, और दूसरों को भी बताते हैं।",rom:"agar sṭāf ye bāteṁ samajh le, to mehmān khush hokar dobārā āte haiṁ, aur dūsroṁ ko bhī batāte haiṁ.",ja:"スタッフの皆さんがこれをわかっていれば、お客様は喜んでまた来て、ほかの人にも伝えてくれます。"},
   {hi:"मुझे लगता है कि मेरे क्लिनिक का अनुभव और आपकी टीम की ताक़त मिलकर अच्छा काम कर सकते हैं।",rom:"mujhe lagtā hai ki mere klinik kā anubhav aur āpkī ṭīm kī tāqat milkar achchhā kām kar sakte haiṁ.",ja:"私の院での経験と、皆さんのチームの力を合わせれば、いい仕事ができると思います。"},
   {hi:"मेरे लिए सबसे ज़रूरी बात एक है। जो इंसान सामने है, उसके लिए पूरी कोशिश करना।",rom:"mere lie sabse zarūrī bāt ek hai. jo insān sāmne hai, uske lie pūrī koshish karnā.",ja:"私にとっていちばん大切なことは一つです。目の前の人に全力を尽くすことです。"},
   {hi:"यही बात मेरे क्लिनिक में भी है, और यही जापानी मेहमाननवाज़ी का दिल भी है।",rom:"yahī bāt mere klinik meṁ bhī hai, aur yahī jāpānī mehmānnavāzī kā dil bhī hai.",ja:"それは私の院でも同じで、日本のおもてなしの心でもあります。"},
   {hi:"अब संक्षेप में। मेरे चार काम हैं, क्लिनिक, सिस्टम, मेहमाननवाज़ी की सलाह, और साके।",rom:"ab sankshep meṁ. mere chār kām haiṁ, klinik, sisṭam, mehmānnavāzī kī salāh, aur sāke.",ja:"まとめます。私の仕事は4つ、院、システム、おもてなしのコンサル、そして日本酒です。"},
   {hi:"अगले क़दम के तौर पर, मैं आपके होटल को देखकर एक छोटा प्रस्ताव भेजना चाहूँगा। विस्तार की बातें हम अंग्रेज़ी में कर सकते हैं।",rom:"agle qadam ke taur par, maiṁ āpke hoṭal ko dekhkar ek chhoṭā prastāv bhejnā chāhūṁgā. vistār kī bāteṁ ham angrezī meṁ kar sakte haiṁ.",ja:"次の一歩として、ホテルを拝見したうえで、小さなご提案をお送りしたいと思います。細かいお話は英語でさせてください。"},
   {hi:"क्या अगले हफ़्ते आपसे एक छोटी मीटिंग हो सकती है? सुनने के लिए दिल से धन्यवाद। अब आपके सवालों का स्वागत है।",rom:"kyā agle hafte āpse ek chhoṭī mīṭing ho saktī hai? sunne ke lie dil se dhanyavād. ab āpke savāloṁ kā svāgat hai.",ja:"来週、短いミーティングをお願いできますか。聞いてくださって、心から感謝します。では、ご質問をどうぞ。"}
  ]},
  task:"インドのホテルの取引先に、4分の会社・事業紹介をする。目的と4つの予告 → 経歴（-ने से पहले/बाद）→ 4つの事業（जो…वह）→ 相手にとっての良さ（अगर…तो）→ 大切にしていること → まとめ → 期限つきの次の一歩、の順で。4分を計って3回通しで練習し、録音を聞き直してから本番にする。",
  taskEn:"Give a 4-minute company and business introduction in Hindi to an Indian hotel partner. State the purpose and preview four points, describe your background (-ने से पहले/बाद), your four businesses (जो…वह), the benefit for them (अगर…तो), your core value, a summary, and a concrete next step. Rehearse three times with a timer and listen to your recording before the real talk.",
  qa:[
   {q:"आपकी सलाह का काम कितने समय का होता है?",qRom:"āpkī salāh kā kām kitne samay kā hotā hai?",a:"यह होटल पर निर्भर करता है। पहले हम एक छोटी बातचीत करेंगे, फिर मैं एक योजना भेजूँगा।",aRom:"yah hoṭal par nirbhar kartā hai. pahle ham ek chhoṭī bātchīt kareṁge, phir maiṁ ek yojnā bhejūṁgā.",ja:"コンサルの期間はどのくらいですか。／ホテルによります。まず短くお話をして、そのあと計画をお送りします。"},
   {q:"आप भारत कब-कब आते हैं?",qRom:"āp Bhārat kab-kab āte haiṁ?",a:"मैं नियमित रूप से भारत आता हूँ। अगली बार आऊँगा, तो आपके होटल ज़रूर आऊँगा।",aRom:"maiṁ niyamit rūp se Bhārat ātā hūṁ. aglī bār āūṁgā, to āpke hoṭal zarūr āūṁgā.",ja:"インドにはどのくらいの頻度で来ますか。／定期的に来ています。次に来るときは、必ずホテルにうかがいます。"},
   {q:"क्या आप फ़ीस के बारे में बता सकते हैं?",qRom:"kyā āp fīs ke bāre meṁ batā sakte haiṁ?",a:"ज़रूर। फ़ीस की बात मैं अंग्रेज़ी में साफ़-साफ़ बताना चाहूँगा, ताकि कोई ग़लतफ़हमी न हो।",aRom:"zarūr. fīs kī bāt maiṁ angrezī meṁ sāf-sāf batānā chāhūṁgā, tāki koī ghalatfahmī na ho.",ja:"費用について教えていただけますか。／もちろんです。誤解がないように、費用のお話は英語ではっきりお伝えしたいと思います。"}
  ],
  check:[
   "最初の30秒で、目的と「4つの話」を言えたか",
   "-ne se pahle / -ne ke bād で経歴を順に話せたか",
   "jo…use・jahāṁ・jinheṁ で事業をくわしく説明できたか",
   "agar…to で相手の場面を描き、良さを伝えられたか",
   "最後に、期限つきの次の一歩と質問の受けつけで締められたか"
  ],
  slide:"1枚目に「今日の4つ」、2枚目に4つの事業を写真つきで4マスに。最後の1枚は「次の一歩：来週のミーティング」だけを大きく書きます。"}
]);

